from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw,
            extendedMarketHours=False
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._previous_fast = None
        self._previous_slow = None

        self._bucket_start = None
        self._bucket_bars = {}
        self._current_day = None

        self._entry_ticket = None
        self._entry_symbol = None
        self._exit_ticket = None

        self._held_symbol = None
        self._held_expiry = None
        self._entry_price = None

        self._no_entry_today = False
        self._equity_liquidation_submitted = False

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self._current_day != current_date:
            if self._bucket_start is not None:
                self._complete_bucket()
            self._current_day = current_date
            self._bucket_start = None
            self._bucket_bars = {}
            self._no_entry_today = False
            self._equity_liquidation_submitted = False

        self._handle_unexpected_equity_position()

        if self._held_symbol is not None and self._held_expiry is not None:
            if current_date >= self._held_expiry.date():
                self._no_entry_today = True
                if self.Portfolio[self._held_symbol].Quantity > 0:
                    self._submit_exit("expiration protection")
            else:
                self._evaluate_held_option_exit(slice)

        if self.spy in slice.Bars:
            self._update_five_minute_bucket(slice.Bars[self.spy])

    def _update_five_minute_bucket(self, minute_bar):
        bar_time = minute_bar.Time
        bar_date = bar_time.date()
        bar_clock = bar_time.time()

        if bar_clock < time(9, 30) or bar_clock >= time(16, 0):
            return

        session_start = datetime(
            bar_date.year,
            bar_date.month,
            bar_date.day,
            9,
            30
        )

        elapsed_minutes = int((bar_time - session_start).total_seconds() // 60)
        bucket_start = session_start + timedelta(
            minutes=(elapsed_minutes // 5) * 5
        )

        if self._bucket_start is not None and bucket_start != self._bucket_start:
            self._complete_bucket()

        if self._bucket_start != bucket_start:
            self._bucket_start = bucket_start
            self._bucket_bars = {}

        self._bucket_bars[bar_time] = minute_bar

    def _complete_bucket(self):
        if self._bucket_start is None:
            return

        bars = [
            self._bucket_bars[key]
            for key in sorted(self._bucket_bars.keys())
        ]

        bucket_start = self._bucket_start
        self._bucket_start = None
        self._bucket_bars = {}

        # A valid five-minute bar requires all five minute bars.
        if len(bars) != 5:
            return

        expected_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if [bar.Time for bar in bars] != expected_times:
            return

        close = bars[-1].Close
        bar_end = bucket_start + timedelta(minutes=5)

        self.fast.Update(bar_end, close)
        self.slow.Update(bar_end, close)

        current_fast = float(self.fast.Current.Value)
        current_slow = float(self.slow.Current.Value)

        bullish_crossover = (
            self.fast.IsReady
            and self.slow.IsReady
            and self._previous_fast is not None
            and self._previous_slow is not None
            and self._previous_fast <= self._previous_slow
            and current_fast > current_slow
        )

        self._previous_fast = current_fast
        self._previous_slow = current_slow

        bar_clock = bar_end.time()

        if (
            bullish_crossover
            and time(9, 45) <= bar_clock <= time(14, 30)
        ):
            self._evaluate_entry(bar_end.date(), close)

    def _evaluate_entry(self, algorithm_date, spy_price):
        if self._no_entry_today:
            return

        if self._held_symbol is not None:
            return

        if self._entry_ticket is not None:
            return

        option_chain = self.CurrentSlice.OptionChains.get(self.option.Symbol)
        if option_chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiry = algorithm_date + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in option_chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no expiration at least seven days out.")
            return

        selected_expiry = expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in option_chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        selected_contract = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self._entry_symbol = selected_contract.Symbol
        self._entry_ticket = self.MarketOrder(
            self._entry_symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            "Entry submitted: {} expiration {} strike {}".format(
                self._entry_symbol,
                selected_expiry,
                selected_contract.Strike
            )
        )

    def _evaluate_held_option_exit(self, slice):
        if self._held_symbol is None:
            return

        held_quantity = self.Portfolio[self._held_symbol].Quantity
        if held_quantity <= 0:
            return

        expiration_date = self._held_expiry.date()
        previous_trading_date = self._previous_trading_date(expiration_date)

        if (
            self.Time.date() == previous_trading_date
            and self.Time.time().hour == 15
            and self.Time.time().minute == 45
        ):
            self._submit_exit("pre-expiration time stop")
            return

        if self._entry_price is None:
            return

        quote = slice.QuoteBars.get(self._held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self._entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self._held_symbol is None:
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity <= 0:
            return

        if self._exit_ticket is not None:
            self.Transactions.CancelOrder(self._exit_ticket.OrderId)

        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -quantity,
            tag=reason
        )

        self.Debug(
            "Exit submitted: {} ({})".format(self._held_symbol, reason)
        )

    def OnOrderEvent(self, order_event):
        if (
            self._entry_ticket is not None
            and order_event.OrderId == self._entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self._held_symbol = self._entry_symbol
                self._held_expiry = self.Securities[
                    self._held_symbol
                ].Symbol.ID.Date
                self._entry_price = order_event.FillPrice

                self.Debug(
                    "Entry filled: {} at {}".format(
                        self._held_symbol,
                        self._entry_price
                    )
                )

                self._entry_ticket = None
                self._entry_symbol = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry order did not fill.")
                self._entry_ticket = None
                self._entry_symbol = None

        if (
            self._exit_ticket is not None
            and order_event.OrderId == self._exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {} at {}".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )
                self._exit_ticket = None
                self._held_symbol = None
                self._held_expiry = None
                self._entry_price = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self._exit_ticket = None

        if (
            order_event.Symbol.SecurityType == SecurityType.Option
            and order_event.OrderType == OrderType.OptionExercise
        ):
            self._no_entry_today = True
            self.Debug(
                "Unexpected option exercise or assignment: {}".format(
                    order_event.Symbol
                )
            )

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0:
            self._no_entry_today = True

            if not self._equity_liquidation_submitted:
                self.Debug(
                    "Unexpected SPY equity position detected; liquidating."
                )
                self.MarketOrder(
                    self.spy,
                    -quantity,
                    tag="Unexpected exercise or assignment liquidation"
                )
                self._equity_liquidation_submitted = True

    def _previous_trading_date(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate 申博

