from AlgorithmImports import *
from datetime import timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy_security = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = self.spy_security.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(timedelta(days=0), timedelta(days=730))
        )
        self.option_symbol = self.option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.entry_ticket = None
        self.entry_symbol = None
        self.held_symbol = None
        self.entry_price = None

        self.exit_tickets = []
        self.equity_exit_ticket = None
        self.block_entries_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self.HandleUnexpectedSpyPosition()

        if self.held_symbol is not None:
            expiry_date = self.held_symbol.ID.Date.date()

            if current_date >= expiry_date:
                self.block_entries_date = current_date
                self.CancelEntryOrder()
                self.ExitHeldPosition("expiration processing")
            elif (
                current_date == self.PreviousTradingDate(expiry_date)
                and self.Time.time() >= datetime.strptime("15:45", "%H:%M").time()
            ):
                self.ExitHeldPosition("expiration time stop")
            else:
                self.CheckProfitTarget(slice)

        if self.block_entries_date != current_date and current_date >= self.block_entries_date if self.block_entries_date else False:
            self.block_entries_date = current_date

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        if not self.fast.IsReady or not self.slow.IsReady:
            previous_fast = None
            previous_slow = None
        else:
            previous_fast = self.fast.Current.Value
            previous_slow = self.slow.Current.Value

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if previous_fast is None or previous_slow is None:
            return
        if not self.fast.IsReady or not self.slow.IsReady:
            return

        bar_time = bar.EndTime.time()
        if bar_time < datetime.strptime("09:45", "%H:%M").time():
            return
        if bar_time > datetime.strptime("14:30", "%H:%M").time():
            return

        if self.fast.Current.Value <= self.slow.Current.Value:
            return
        if previous_fast > previous_slow:
            return

        current_date = self.Time.date()

        if self.block_entries_date == current_date:
            return
        if self.entry_ticket is not None:
            return
        if self.held_symbol is not None:
            return

        current_slice = self.CurrentSlice
        self.SelectAndEnterCall(current_slice, bar.Close, current_date)

    def SelectAndEnterCall(self, slice: Slice, spy_price: float, current_date):
        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiry = current_date + timedelta(days=7)

        eligible_contracts = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not eligible_contracts:
            self.Debug("Skipped entry: no eligible call expiration.")
            return

        selected_expiry = min(
            contract.Expiry.date() for contract in eligible_contracts
        )

        strike_floor = spy_price * 1.01
        candidates = [
            contract for contract in eligible_contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= strike_floor
        ]

        if not candidates:
            self.Debug("Skipped entry: no call at or above 1% OTM.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            "Entry submitted: {} strike {:.2f} expiry {}".format(
                selected.Symbol,
                selected.Strike,
                selected.Expiry.date()
            )
        )

    def CheckProfitTarget(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return
        if self.HasOpenExitOrder():
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        contract = next(
            (item for item in chain if item.Symbol == self.held_symbol),
            None
        )
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self.ExitHeldPosition("50% profit target")

    def ExitHeldPosition(self, reason: str):
        if self.held_symbol is None:
            return
