from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    FAST_PERIOD = 5
    SLOW_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.SetSecurityInitializer(
            lambda security: security.SetDataNormalizationMode(
                DataNormalizationMode.Raw
            )
        )

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(timedelta(0), timedelta(days=365))
        )
        self.option_symbol = self.option.Symbol

        self.fast_values = deque(maxlen=self.FAST_PERIOD)
        self.slow_values = deque(maxlen=self.SLOW_PERIOD)
        self.previous_fast = None
        self.previous_slow = None

        self.aggregate_bucket_end = None
        self.aggregate_next_start = None
        self.aggregate_invalid = False
        self.aggregate_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.no_entry_date = None
        self.equity_cleanup_ticket = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_equity_position()

        current_date = self.Time.date()
        current_time = self.Time.time()

        if self.held_option is not None:
            expiry_date = self.held_option.ID.Date.date()

            if current_date == expiry_date and current_time >= datetime.min.time().replace(
                hour=9, minute=30
            ):
                self.no_entry_date = current_date
                self._submit_exit("expiration-day liquidation")
            elif (
                current_time >= datetime.min.time().replace(hour=15, minute=45)
                and current_date == self._previous_trading_day(expiry_date)
            ):
                self._submit_exit("pre-expiration time stop")
            else:
                self._check_profit_target(slice)

        bar = self._get_spy_bar(slice)
        if bar is not None:
            self._process_minute_bar(bar, slice)

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status not in (
            OrderStatus.PartiallyFilled,
            OrderStatus.Filled
        ):
            return

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.FillQuantity > 0:
                if self.held_option is None:
                    self.held_option = order_event.Symbol
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        "ENTRY {} x{} @ {:.2f}".format(
                            order_event.Symbol.Value,
                            order_event.FillQuantity,
                            order_event.FillPrice
                        )
                    )
            if order_event.Status == OrderStatus.Filled:
                self.entry_ticket = None

        elif (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "EXIT {} x{} @ {:.2f}".format(
                        order_event.Symbol.Value,
                        abs(order_event.FillQuantity),
                        order_event.FillPrice
                    )
                )
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None

        elif (
            self.equity_cleanup_ticket is not None
            and order_event.OrderId == self.equity_cleanup_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Unexpected SPY equity position liquidated")
            self.equity_cleanup_ticket = None
            self.no_entry_date = self.Time.date()

    def OnEndOfAlgorithm(self):
        if self.held_option is not None:
            self._submit_exit("end-of-backtest liquidation")

    def _get_spy_bar(self, slice: Slice):
        try:
            return slice.Bars.get(self.spy)
        except Exception:
            return None

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        start = bar.Time
        if start.tzinfo is not None:
            start = start.replace(tzinfo=None)

        if start.time() < datetime.min.time().replace(hour=9, minute=30):
            return
        if start.time() >= datetime.min.time().replace(hour=16):
            return

        bucket_end_minute = ((start.minute // 5) + 1) * 5
        bucket_end = start.replace(
            minute=0,
            second=0,
            microsecond=0
        ) + timedelta(minutes=bucket_end_minute)

        if self.aggregate_bucket_end != bucket_end:
            self.aggregate_bucket_end = bucket_end
            self.aggregate_next_start = start
            self.aggregate_invalid = False
            self.aggregate_bars = []

        if start != self.aggregate_next_start:
            self.aggregate_invalid = True

        self.aggregate_bars.append(bar)
        self.aggregate_next_start = start + timedelta(minutes=1)

        if start + timedelta(minutes=1) != bucket_end:
            return

        completed = (
            not self.aggregate_invalid
            and len(self.aggregate_bars) == 5
            and self.aggregate_next_start == bucket_end
        )

        if completed:
            close = self.aggregate_bars[-1].Close
            self._process_five_minute_close(bucket_end, close, slice)

        self.aggregate_bars = []

    def _process_five_minute_close(self, end_time, close, slice: Slice):
        previous_fast = self.previous_fast
        previous_slow = self.previous_slow

        self.fast_values.append(close)
        self.slow_values.append(close)

        if len(self.fast_values) < self.FAST_PERIOD:
            self.previous_fast = None
        else:
            self.previous_fast = sum(self.fast_values) / len(self.fast_values)

        if len(self.slow_values) < self.SLOW_PERIOD:
            self.previous_slow = None
        else:
            self.previous_slow = sum(self.slow_values) / len(self.slow_values)

        if (
            previous_fast is None
            or previous_slow is None
            or self.previous_fast is None
            or self.previous_slow is None
        ):
            return

        eligible_time = (
            datetime.min.time().replace(hour=9, minute=45)
            <= end_time.time()
            <= datetime.min.time().replace(hour=14, minute=30)
        )

        crossover = (
            previous_fast <= previous_slow
            and self.previous_fast > self.previous_slow
        )

        if crossover and eligible_time:
            self._try_enter(slice, close)

    def _try_enter(self, slice: Slice, spy_price: float):
        today = self.Time.date()

        if self.no_entry_date == today:
            return
        if self.held_option is not None:
            return
        if self.entry_ticket is not None:
            return

        chain = self._get_option_chain(slice)
        if chain is None:
            self.Debug("SKIP entry: no option chain")
            return

        minimum_expiry = today + timedelta(days=7)
        expiries = sorted({
            contract.Expiry.date()
            for contract in self._contracts(chain)
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("SKIP entry: no expiration at least 7 days out")
            return

        expiry = expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in self._contracts(chain)
            if (
                contract.Expiry.date() == expiry
                and contract.Right == OptionRight.Call
                and contract.Strike >= minimum_strike
            )
        ]

        if not candidates:
            self.Debug("SKIP entry: no qualifying call")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

    def _get_option_chain(self, slice: Slice):
        try:
            chains = slice.OptionChains
            chains = chains.Values if hasattr(chains, "Values") else chains.values()

            for chain in chains:
                if chain.Symbol == self.option_symbol:
                    return chain
        except Exception:
            return None

        return None

    def _contracts(self, chain):
        try:
            contracts = chain.Contracts
            return (
                list(contracts.Values)
                if hasattr(contracts, "Values")
                else list(contracts.values())
            )
        except Exception:
            return []

    def _check_profit_target(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return
        if self.exit_ticket is not None:
            return

        try:
            quote = slice.QuoteBars.get(self.held_option)
        except Exception:
            quote = None

        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.held_option is None or self.exit_ticket is not None:
            return

        security = self.Securities[self.held_option]
        quantity = security.Holdings.Quantity

        if quantity == 0:
            return

        if self.entry_ticket is not None:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity
        )
        self.Debug(
            "EXIT submitted: {} ({})".format(
                self.held_option.Value,
                reason
            )
        )

    def _handle_unexpected_equity_position(self):
        holdings = self.Portfolio[self.spy].Quantity

        if holdings != 0 and self.equity_cleanup_ticket is None:
            self.no_entry_date = self.Time.date()
            self.Debug(
                "Unexpected exercise or assignment: liquidating SPY equity"
            )
            self.equity_cleanup_ticket = self.MarketOrder(
                self.spy,
                -holdings
            )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate.date() if hasattr(candidate, "date") else candidate

