        if order_event.Status not in (
            OrderStatus.PartiallyFilled,
            OrderStatus.Filled
        ):
            return

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.FillQuantity > 0:
                if self.held_option is None:
                    self.held_option = order_event.Symbol
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        "ENTRY {} x{} @ {:.2f}".format(
                            order_event.Symbol.Value,
                            order_event.FillQuantity,
                            order_event.FillPrice
                        )
                    )
            if order_event.Status == OrderStatus.Filled:
                self.entry_ticket = None

        elif (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "EXIT {} x{} @ {:.2f}".format(
                        order_event.Symbol.Value,
                        abs(order_event.FillQuantity),
                        order_event.FillPrice
                    )
                )
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None

        elif (
            self.equity_cleanup_ticket is not None
            and order_event.OrderId == self.equity_cleanup_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Unexpected SPY equity position liquidated")
            self.equity_cleanup_ticket = None
            self.no_entry_date = self.Time.date()

    def OnEndOfAlgorithm(self):
        if self.held_option is not None:
            self._submit_exit("end-of-backtest liquidation")

    def _get_spy_bar(self, slice: Slice):
        try:
            return slice.Bars.get(self.spy)
        except Exception:
            return None

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        start = bar.Time
        if start.tzinfo is not None:
            start = start.replace(tzinfo=None)

        if start.time() < datetime.min.time().replace(hour=9, minute=30):
            return
        if start.time() >= datetime.min.time().replace(hour=16):
            return

        bucket_end_minute = ((start.minute // 5) + 1) * 5
        bucket_end = start.replace(
            minute=0,
            second=0,
            microsecond=0
        ) + timedelta(minutes=bucket_end_minute)

        if self.aggregate_bucket_end != bucket_end:
            self.aggregate_bucket_end = bucket_end
            self.aggregate_next_start = start
            self.aggregate_invalid = False
            self.aggregate_bars = []

        if start != self.aggregate_next_start:
            self.aggregate_invalid = True

        self.aggregate_bars.append(bar)
        self.aggregate_next_start = start + timedelta(minutes=1)

        if start + timedelta(minutes=1) != bucket_end:
            return

        completed = (
            not self.aggregate_invalid
            and len(self.aggregate_bars) == 5
            and self.aggregate_next_start == bucket_end
        )

        if completed:
            close = self.aggregate_bars[-1].Close
            self._process_five_minute_close(bucket_end, close, slice)

        self.aggregate_bars = []

    def _process_five_minute_close(self, end_time, close, slice: Slice):
        previous_fast = self.previous_fast
        previous_slow = self.previous_slow

        self.fast_values.append(close)
        self.slow_values.append(close)

        if len(self.fast_values) < self.FAST_PERIOD:
            self.previous_fast = None
        else:
            self.previous_fast = sum(self.fast_values) / len(self.fast_values)

        if len(self.slow_values) < self.SLOW_PERIOD:
            self.previous_slow = None
        else:
            self.previous_slow = sum(self.slow_values) / len(self.slow_values)

        if (
            previous_fast is None
            or previous_slow is None
            or self.previous_fast is None
            or self.previous_slow is None
        ):
            return

        eligible_time = (
            datetime.min.time().replace(hour=9, minute=45)
            <= end_time.time()
            <= datetime.min.time().replace(hour=14, minute=30)
        )

        crossover = (
            previous_fast <= previous_slow
            and self.previous_fast > self.previous_slow
        )

        if crossover and eligible_time:
            self._try_enter(slice, close)

    def _try_enter(self, slice: Slice, spy_price: float):
        today = self.Time.date()

        if self.no_entry_date == today:
            return
        if self.held_option is not None:
            return
        if self.entry_ticket is not None:
            return

        chain = self._get_option_chain(slice)
        if chain is None:
            self.Debug("SKIP entry: no option chain")
            return

        minimum_expiry = today + timedelta(days=7)
        expiries = sorted({
            contract.Expiry.date()
            for contract in self._contracts(chain)
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("SKIP entry: no expiration at least 7 days out")
            return

        expiry = expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in self._contracts(chain)
            if (
                contract.Expiry.date() == expiry
                and contract.Right == OptionRight.Call
                and contract.Strike >= minimum_strike
            )
        ]

        if not candidates:
            self.Debug("SKIP entry: no qualifying call")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

    def _get_option_chain(self, slice: Slice):
        try:
            chains = slice.OptionChains
            chains = chains.Values if hasattr(chains, "Values") else chains.values()

            for chain in chains:
                if chain.Symbol == self.option_symbol:
                    return chain
        except Exception:
            return None

        return None

    def _contracts(self, chain):
        try:
            contracts = chain.Contracts
            return (
                list(contracts.Values)
                if hasattr(contracts, "Values")
                else list(contracts.values())
            )
        except Exception:
            return []

    def _check_profit_target(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return
        if self.exit_ticket is not None:
            return

        try:
            quote = slice.QuoteBars.get(self.held_option)
        except Exception:
            quote = None

        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.held_option is None or self.exit_ticket is not None:
            return

        security = self.Securities[self.held_option]
        quantity = security.Holdings.Quantity

        if quantity == 0:
            return

        if self.entry_ticket is not None:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity
        )
        self.Debug(
            "EXIT submitted: {} ({})".format(
                self.held_option.Value,
                reason
            )
        )

    def _handle_unexpected_equity_position(self):
        holdings = self.Portfolio[self.spy].Quantity

        if holdings != 0 and self.equity_cleanup_ticket is None:
            self.no_entry_date = self.Time.date()
            self.Debug(
                "Unexpected exercise or assignment: liquidating SPY equity"
            )
            self.equity_cleanup_ticket = self.MarketOrder(
                self.spy,
                -holdings
            )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate.date() if hasattr(candidate, "date") else candidate

from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw,
            extendedMarketHours=False
        ).Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(-100, 100, 0, 365)
        self.option_canonical = self.spy_option.Symbol

        self.fast_period = 5
        self.slow_period = 20

        self.fast_closes = []
        self.slow_closes = []

        self.current_bucket_date = None
        self.current_bucket_start = None
        self.current_bucket_bars = []

        self.entry_ticket = None
        self.entry_order_id = None
        self.entry_price = None

        self.held_symbol = None
        self.exit_ticket = None
        self.exit_order_id = None

        self.no_entry_today = False
        self.cleanup_order_id = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()
        current_time = self.Time.time()

        if self.current_bucket_date != current_date:
            self.current_bucket_date = current_date
            self.current_bucket_start = None
            self.current_bucket_bars = []
            self.no_entry_today = False

        self._handle_unexpected_spy_position()

        if self.held_symbol is not None:
            expiry_date = self._held_expiry_date()

            if expiry_date is not None and current_date >= expiry_date:
                self.no_entry_today = True
                self._submit_exit("expiration processing")
            else:
                self._evaluate_exit_conditions(slice, current_date, current_time)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        signal_bar = self._update_five_minute_bar(spy_bar)
        if signal_bar is None:
            return

        if self.no_entry_today:
            return

        if self.held_symbol is not None:
            return

        if self._entry_order_is_open():
            return

        bar_end = signal_bar.EndTime
        if hasattr(bar_end, "astimezone"):
            bar_end = bar_end.replace(tzinfo=None)

        end_time = bar_end.time()
        if not (time(9, 45) <= end_time <= time(14, 30)):
            return

        if len(self.fast_closes) < self.slow_period + 1:
            return

        previous_fast = sum(self.fast_closes[-2-self.fast_period+1:-1]) / self.fast_period
        previous_slow = sum(self.slow_closes[-2-self.slow_period+1:-1]) / self.slow_period
        current_fast = sum(self.fast_closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.slow_closes[-self.slow_period:]) / self.slow_period

        bullish_crossover = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if bullish_crossover:
            self._try_enter(slice, spy_bar.Close)

    def _update_five_minute_bar(self, minute_bar):
        bar_time = minute_bar.Time
        if hasattr(bar_time, "astimezone"):
            bar_time = bar_time.replace(tzinfo=None)

        local_date = bar_time.date()
        local_time = bar_time.time()

        if local_time < time(9, 30) or local_time >= time(16, 0):
            return None

        bucket_minute = (bar_time.minute // 5) * 5
        bucket_start = datetime(
            local_date.year,
            local_date.month,
            local_date.day,
            bar_time.hour,
            bucket_minute
        )

        if self.current_bucket_start is None:
            self.current_bucket_start = bucket_start
            self.current_bucket_bars = []

        if bucket_start != self.current_bucket_start:
            completed = None
            if len(self.current_bucket_bars) == 5:
                completed = self._create_five_minute_bar(
                    self.current_bucket_start,
                    self.current_bucket_bars
                )

            self.current_bucket_start = bucket_start
            self.current_bucket_bars = []

            if completed is not None:
                self._update_averages(completed.Close)
                if len(self.fast_closes) >= self.slow_period:
                    return completed

        expected_time = self.current_bucket_start + timedelta(
            minutes=len(self.current_bucket_bars)
        )

        if bar_time != expected_time:
            self.current_bucket_bars = []
            self.current_bucket_start = bucket_start

        self.current_bucket_bars.append(minute_bar)

        if len(self.current_bucket_bars) == 5:
            completed = self._create_five_minute_bar(
                self.current_bucket_start,
                self.current_bucket_bars
            )
            self._update_averages(completed.Close)
            self.current_bucket_bars = []
            self.current_bucket_start = self.current_bucket_start + timedelta(minutes=5)

            if len(self.fast_closes) >= self.slow_period:
                return completed

        return None

    def _create_five_minute_bar(self, start_time, bars):
        return TradeBar(
            start_time,
            self.spy,
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars),
            timedelta(minutes=5)
        )

    def _update_averages(self, close):
        self.fast_closes.append(float(close))
        self.slow_closes.append(float(close))

        max_period = max(self.fast_period, self.slow_period) + 2
        if len(self.fast_closes) > max_period:
            self.fast_closes.pop(0)
        if len(self.slow_closes) > max_period:
            self.slow_closes.pop(0)

    def _try_enter(self, slice, spy_price):
        chain = slice.OptionChains.get(self.option_canonical)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = list(chain)
        expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no expiration at least 7 calendar days out.")
            return

        selected_expiry = expiries[0]
        minimum_strike = float(spy_price) * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.entry_order_id = self.entry_ticket.OrderId

    def _evaluate_exit_conditions(self, slice, current_date, current_time):
        if self.held_symbol is None or self.entry_price is None:
            return

        quote = slice.QuoteBars.get(self.held_symbol)
        midpoint = None

        if quote is not None and quote.Bid is not None and quote.Ask is not None:
            bid = float(quote.Bid.Close)
            ask = float(quote.Ask.Close)
            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0

        if midpoint is not None and midpoint >= 1.50 * self.entry_price:
            self._cancel_open_exit()
            self._submit_exit("50% profit target")
            return

        expiry_date = self._held_expiry_date()
        if expiry_date is None:
            return

        prior_trading_day = self._prior_trading_day(expiry_date)
        if (
            current_date == prior_trading_day and
            current_time >= time(15, 45)
        ):
            self._submit_exit("pre-expiration time stop")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self._is_order_open(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self._cancel_open_exit()

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.exit_order_id = self.exit_ticket.OrderId
        self.Debug("Submitted exit for {}: {}".format(self.held_symbol, reason))

    def _cancel_open_exit(self):
        if self.exit_ticket is not None and self._is_order_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replaced by higher-priority exit condition")

    def _entry_order_is_open(self):
        return (
            self.entry_ticket is not None and
            self._is_order_open(self.entry_ticket)
        )

    def _is_order_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        ]

    def _held_expiry_date(self):
        if self.held_symbol is None:
            return None

        security = self.Securities[self.held_symbol]
        return security.Symbol.ID.Date.date()

    def _prior_trading_day(self, expiry_date):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = expiry_date - timedelta(days=1)

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self.no_entry_today = True

        if self.cleanup_order_id is None:
            self.Debug(
                "Unexpected SPY equity position detected; liquidating immediately."
            )
            ticket = self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment cleanup"
            )
            self.cleanup_order_id = ticket.OrderId

    def OnOrderEvent(self, order_event):
        if order_event.Status in [
            OrderStatus.PartiallyFilled,
            OrderStatus.Filled
        ] and order_event.FillQuantity != 0:

            if (
                self.entry_order_id is not None and
                order_event.OrderId == self.entry_order_id
            ):
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entered 1 SPY call {} at filled price {:.4f}".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )

                if order_event.Status == OrderStatus.Filled:
                    self.entry_ticket = None
                    self.entry_order_id = None

            elif (
                self.exit_order_id is not None and
                order_event.OrderId == self.exit_order_id
            ):
                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.Debug("Exited SPY call {}".format(order_event.Symbol))
                    self.held_symbol = None
                    self.entry_price = None
                    self.exit_ticket = None
                    self.exit_order_id = None

        if (
            self.entry_order_id is not None and
            order_event.OrderId == self.entry_order_id and
            order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]
        ):
            self.entry_ticket = None
            self.entry_order_id = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected option exercise or assignment event received.")
        self.no_entry_today = True

