        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.SubmitOptionExit("profit target")

    def HandleTimeStop(self, today):
        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        previous_trading_day = self.PreviousTradingDay(expiry_date)

        if (
            today == previous_trading_day and
            self.Time.hour > 15 or
            today == previous_trading_day and
            self.Time.hour == 15 and self.Time.minute >= 45
        ):
            self.SubmitOptionExit("time stop")

    def HandleExpiration(self, today):
        if self.held_symbol is None:
