        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.fast_period = 5
        self.slow_period = 20
        self.fast_window = RollingWindow[float](self.fast_period)
        self.slow_window = RollingWindow[float](self.slow_period)

        self.previous_fast = None
        self.previous_slow = None

        self.current_slice = None
        self.entry_ticket = None
        self.entry_order_id = None
        self.held_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.no_entry_date = None
        self.equity_exit_pending = False

    def OnData(self, slice: Slice):
        self.current_slice = slice
        today = self.Time.date()

        self.HandleUnexpectedEquityPosition()
        self.HandleExpiration(today)
        self.HandleTimeStop(today)
        self.HandleProfitTarget(slice)

        if self.equity_exit_pending and self.Portfolio[self.spy].Quantity == 0:
            self.equity_exit_pending = False

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        if self.current_slice is None:
            return

        bar_time = bar.EndTime
        if bar_time.tzinfo is not None:
            bar_time = bar_time.astimezone(
                self.TimeZone.ToDateTimeZone().tzinfo
            )

        current_fast = None
        current_slow = None

        self.fast_window.Add(float(bar.Close))
        self.slow_window.Add(float(bar.Close))

        if self.fast_window.IsReady:
            current_fast = sum(self.fast_window) / self.fast_period
        if self.slow_window.IsReady:
            current_slow = sum(self.slow_window) / self.slow_period

        if current_fast is None or current_slow is None:
            self.previous_fast = current_fast
            self.previous_slow = current_slow
            return

        bullish_cross = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if not bullish_cross:
            return

        local_time = bar.EndTime
        if local_time.tzinfo is not None:
            local_time = local_time.astimezone(
                self.TimeZone.ToDateTimeZone().tzinfo
            )

        if not (local_time.hour == 9 and local_time.minute >= 45) and not (
            10 <= local_time.hour <= 13
        ) and not (local_time.hour == 14 and local_time.minute <= 30):
            return

        today = self.Time.date()
        if self.no_entry_date == today:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self.IsOpen(self.entry_ticket):
            return

        self.TryEnterCall()

    def TryEnterCall(self):
        if self.spy not in self.current_slice.Bars:
            self.Debug("Skipped call selection: no current SPY price.")
            return

        spy_price = float(self.current_slice.Bars[self.spy].Close)
        chains = self.current_slice.OptionChains

        if chains is None or len(chains) == 0:
            self.Debug("Skipped call selection: no option chain.")
            return

        today = self.Time.date()
        eligible_expirations = []

        for chain in chains.Values:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()
                if expiry_date >= today + timedelta(days=7):
                    eligible_expirations.append(expiry_date)

        if not eligible_expirations:
            self.Debug("Skipped call selection: no eligible expiration.")
            return

        selected_expiry = min(eligible_expirations)
        candidates = []

        for chain in chains.Values:
            for contract in chain.Contracts.Values:
                if contract.Expiry.date() != selected_expiry:
                    continue
                if contract.Right != OptionRight.Call:
                    continue
                if float(contract.Strike) >= 1.01 * spy_price:
                    candidates.append(contract)

