from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallStrategy(QCAlgorithm):
    FAST_PERIOD = 5
    SLOW_PERIOD = 20
    MIN_OPTION_DTE = 7

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(timedelta(0), timedelta(days=730))
        )
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(self.FAST_PERIOD)
        self.slow = SimpleMovingAverage(self.SLOW_PERIOD)

        self._five_minute_bucket = None
        self._five_minute_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_date = None
        self.blocked_entry_dates = set()
        self.equity_liquidation_ticket = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        if self.Portfolio[self.spy].Quantity != 0:
            if self.equity_liquidation_ticket is None or not self.equity_liquidation_ticket.Status.IsOpen():
                self.Debug("Unexpected exercise or assignment created SPY equity; liquidating.")
                self.equity_liquidation_ticket = self.MarketOrder(
                    self.spy,
                    -self.Portfolio[self.spy].Quantity,
                    tag="Unexpected exercise or assignment liquidation"
                )

        if self.held_option is not None and self.expiration_date is not None:
            if today >= self.expiration_date:
                self.blocked_entry_dates.add(today)
                self._liquidate_option("Expiration liquidation")
            elif (
                today == self.expiration_date - timedelta(days=1)
                and self.Time.time() >= time(15, 45)
            ):
                self._liquidate_option("Pre-expiration time stop")

        if self.held_option is not None and self.exit_ticket is None:
            contract = self._get_current_contract(slice, self.held_option)
            if contract is not None:
                bid = contract.BidPrice
                ask = contract.AskPrice
                if bid is not None and ask is not None and bid > 0 and ask > 0:
                    midpoint = (bid + ask) / 2
                    if midpoint >= 1.50 * self.entry_price:
                        self._liquidate_option("50% profit target")

        if self.spy not in slice.Bars:
            return

        minute_bar = slice.Bars[self.spy]
        self._update_five_minute_bar(minute_bar, slice)

    def _update_five_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        minute_end = minute_bar.EndTime
        session_start = time(9, 31)
        session_end = time(16, 0)

        if minute_end.time() < session_start or minute_end.time() > session_end:
            return

        bucket_end = self._bucket_end(minute_end)

        if self._five_minute_bucket != bucket_end:
            self._five_minute_bucket = bucket_end
            self._five_minute_bars = []

            if minute_end.minute % 5 != 1:
                return

        if not self._five_minute_bars:
            expected_end = bucket_end - timedelta(minutes=4)
        else:
            expected_end = self._five_minute_bars[-1].EndTime + timedelta(minutes=1)

        if minute_end != expected_end:
            self._five_minute_bars = []
            return

        self._five_minute_bars.append(minute_bar)

        if len(self._five_minute_bars) != 5:
            return

        consolidated_close = self._five_minute_bars[-1].Close
        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(IndicatorDataPoint(bucket_end, consolidated_close))
        self.slow.Update(IndicatorDataPoint(bucket_end, consolidated_close))

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if (
            bullish_cross
            and time(9, 45) <= bucket_end.time() <= time(14, 30)
        ):
            self._try_enter(slice, consolidated_close)

    def _bucket_end(self, minute_end: datetime) -> datetime:
        base = datetime.combine(minute_end.date(), time(9, 35))
        elapsed_minutes = int((minute_end - base).total_seconds() // 60)
        bucket_minutes = (elapsed_minutes // 5) * 5
        return base + timedelta(minutes=bucket_minutes)

    def _try_enter(self, slice: Slice, spy_price):
        today = self.Time.date()

        if today in self.blocked_entry_dates:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and self.entry_ticket.Status.IsOpen():
            return

        chain = None
        if self.option_symbol in slice.OptionChains:
            chain = slice.OptionChains[self.option_symbol]
        else:
            for candidate in slice.OptionChains.Values:
                if candidate.Symbol == self.option_symbol:
                    chain = candidate
                    break

        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = today + timedelta(days=self.MIN_OPTION_DTE)
        contracts = list(chain.Contracts.Values)

        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration satisfies the DTE rule.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * float(spy_price)

        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at the selected expiration.")
            return

        candidates.sort(key=lambda contract: (float(contract.Strike), str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            "Entry submitted: {} expiration {} strike {}".format(
                selected.Symbol, selected_expiry, selected.Strike
            )
        )

    def _get_current_contract(self, slice: Slice, symbol: Symbol):
        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(symbol)
            if contract is not None:
                return contract
        return None

    def _liquidate_option(self, reason: str):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status.IsOpen():
            self.exit_ticket.Cancel("Replacing open exit order")

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: {} ({})".format(self.held_option, reason))

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status in [OrderStatus.Filled, OrderStatus.PartiallyFilled]:
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.expiration_date = self.Securities[order_event.Symbol].Symbol.ID.Date.date()
                self.entry_ticket = None
                self.Debug(
                    "Entry filled: {} at {}".format(
                        self.held_option, self.entry_price
                    )
                )
            elif order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ]:
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status in [
                OrderStatus.Filled,
                OrderStatus.PartiallyFilled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ]:
                if order_event.Status in [OrderStatus.Filled, OrderStatus.PartiallyFilled]:
                    self.Debug(
                        "Exit filled: {} at {}".format(
                            order_event.Symbol, order_event.FillPrice
                        )
                    )
                    if self.Portfolio[order_event.Symbol].Quantity == 0:
                        self.held_option = None
                        self.entry_price = None
                        self.expiration_date = None
                self.exit_ticket = None

