            return

        minute_bar = slice.Bars[self.spy]
        self._update_five_minute_bar(minute_bar, slice)

    def _update_five_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        minute_end = minute_bar.EndTime
        session_start = time(9, 31)
        session_end = time(16, 0)

        if minute_end.time() < session_start or minute_end.time() > session_end:
            return

        bucket_end = self._bucket_end(minute_end)

        if self._five_minute_bucket != bucket_end:
            self._five_minute_bucket = bucket_end
            self._five_minute_bars = []

            if minute_end.minute % 5 != 1:
                return

        if not self._five_minute_bars:
            expected_end = bucket_end - timedelta(minutes=4)
        else:
            expected_end = self._five_minute_bars[-1].EndTime + timedelta(minutes=1)

        if minute_end != expected_end:
            self._five_minute_bars = []
            return

        self._five_minute_bars.append(minute_bar)

        if len(self._five_minute_bars) != 5:
            return

