            return

        if self.no_entry_date == self.Time.date():
            return

        if self.HasOptionHolding() or self.IsEntryOrderOpen():
            return

        self.TryEnterCall(slice)

    def TryEnterCall(self, slice: Slice):
        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None or spy_bar.Close <= 0:
            self.Debug("Skipped entry: SPY price unavailable.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)
        eligible = []

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue
                expiry_date = contract.Expiry.date()
                if expiry_date < minimum_expiry:
                    continue
                if contract.Strike < spy_bar.Close * 1.01:
                    continue
                eligible.append(contract)

        if not eligible:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in eligible)
        selected = sorted(
            (
                contract for contract in eligible
                if contract.Expiry.date() == nearest_expiry
            ),
