from datetime import datetime, timedelta


class SpyBullishCallAlgorithm(QCAlgorithm):
    FAST_PERIOD = 5
    SLOW_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(0, 370)
        )

        self.fast = SimpleMovingAverage(self.FAST_PERIOD)
        self.slow = SimpleMovingAverage(self.SLOW_PERIOD)

        self._previous_fast = None
        self._previous_slow = None
        self._bucket_start = None
        self._bucket_bars = {}

        self._entry_ticket = None
        self._exit_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._blocked_entry_date = None
        self._equity_liquidation_ticket = None

    def OnData(self, data: Slice):
        self._handle_unexpected_spy_equity(data)
        self._process_expiration_and_exits(data)

        if not data.Bars.ContainsKey(self.spy):
            return

        spy_bar = data.Bars[self.spy]
        local_start = self.Time

        if not self._is_regular_session_minute(local_start):
            return

        completed_bar = self._update_five_minute_bar(local_start, spy_bar.Close)
        if completed_bar is None:
            return

        bar_end, close = completed_bar
        self.fast.Update(bar_end, close)
        self.slow.Update(bar_end, close)

        if not self.fast.IsReady or not self.slow.IsReady:
            self._previous_fast = self.fast.Current.Value
            self._previous_slow = self.slow.Current.Value
            return

        bullish_cross = (
            self._previous_fast is not None
            and self._previous_slow is not None
            and self._previous_fast <= self._previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        self._previous_fast = self.fast.Current.Value
        self._previous_slow = self.slow.Current.Value

        bar_end_time = bar_end.time()
        eligible_time = (
            bar_end_time >= datetime.strptime("09:45", "%H:%M").time()
            and bar_end_time <= datetime.strptime("14:30", "%H:%M").time()
        )

        if bullish_cross and eligible_time:
            self._try_enter(data, spy_bar.Close)

    def _is_regular_session_minute(self, time_value):
        current = time_value.time()
        return (
            current >= datetime.strptime("09:30", "%H:%M").time()
            and current < datetime.strptime("16:00", "%H:%M").time()
        )

    def _update_five_minute_bar(self, minute_start, close):
        session_start = minute_start.replace(
            hour=9, minute=30, second=0, microsecond=0
        )
        elapsed_minutes = int((minute_start - session_start).total_seconds() / 60)
        bucket_index = elapsed_minutes // 5
        bucket_start = session_start + timedelta(minutes=bucket_index * 5)

        if self._bucket_start is not None and bucket_start != self._bucket_start:
            self._bucket_bars = {}

        self._bucket_start = bucket_start
        self._bucket_bars[minute_start] = close

        expected_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if not all(expected in self._bucket_bars for expected in expected_times):
            return None

        bucket_end = bucket_start + timedelta(minutes=5)
        completed_close = self._bucket_bars[expected_times[-1]]
        self._bucket_bars = {}
        return bucket_end, completed_close

    def _try_enter(self, data, spy_price):
        current_date = self.Time.date()

        if self._blocked_entry_date == current_date:
            return

        if self._held_symbol is not None:
            return

        if self._entry_ticket is not None and self._is_open_order(self._entry_ticket):
            return

        chain = None
        for candidate_chain in data.OptionChains:
            if candidate_chain.Symbol == self.spy_option.Symbol:
                chain = candidate_chain
                break

        if chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        minimum_expiry = current_date + timedelta(days=7)
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped call selection: no expiration at least 7 days out.")
            return

        selected_expiry = expirations[0]
        minimum_strike = float(spy_price) * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call contract.")
            return

        candidates.sort(
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )
        selected = candidates[0]

        self._entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Submitted entry for " + str(selected.Symbol))

    def _process_expiration_and_exits(self, data):
        if self._held_symbol is None:
            return

        holding = self.Portfolio[self._held_symbol]
        if not holding.Invested:
            return

        expiry_date = self._held_symbol.ID.Date.date()
        today = self.Time.date()
        current_time = self.Time.time()

        if today >= expiry_date and current_time >= datetime.strptime(
            "09:30", "%H:%M"
        ).time():
            self._blocked_entry_date = today
            self._submit_exit("expiration processing")
            return

        previous_trading_day = self._previous_trading_day(expiry_date)

        if (
            today == previous_trading_day
            and current_time >= datetime.strptime("15:45", "%H:%M").time()
        ):
            self._submit_exit("expiration time stop")
            return

        if self._exit_ticket is not None and self._is_open_order(self._exit_ticket):
            return

        if not data.QuoteBars.ContainsKey(self._held_symbol):
            return

        quote = data.QuoteBars[self._held_symbol]

        try:
            bid = float(quote.Bid.Close)
            ask = float(quote.Ask.Close)
        except Exception:
            return

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self._entry_price is not None and midpoint >= 1.5 * self._entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self._held_symbol is None:
            return

        holding = self.Portfolio[self._held_symbol]
        quantity = int(holding.Quantity)

        if quantity == 0:
            return

        if self._exit_ticket is not None and self._is_open_order(self._exit_ticket):
            return

        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Submitted exit for " + str(self._held_symbol) + ": " + reason)

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _handle_unexpected_spy_equity(self, data):
        quantity = int(self.Portfolio[self.spy].Quantity)

        if quantity == 0:
            return

        if (
            self._equity_liquidation_ticket is not None
            and self._is_open_order(self._equity_liquidation_ticket)
        ):
            return

        self.Debug("Unexpected SPY equity position; liquidating immediately.")
        self._equity_liquidation_ticket = self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise or assignment"
        )

    def _is_open_order(self, ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def OnOrderEvent(self, order_event):
        if (
            self._entry_ticket is not None
            and order_event.OrderId == self._entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self._held_symbol = self._entry_ticket.Symbol
                self._entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled: "
                    + str(self._held_symbol)
                    + " at "
                    + str(self._entry_price)
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self._entry_ticket = None

        if (
            self._exit_ticket is not None
            and order_event.OrderId == self._exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: " + str(self._exit_ticket.Symbol))
                self._exit_ticket = None
                self._held_symbol = None
                self._entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self._exit_ticket = None

        if (
            self._equity_liquidation_ticket is not None
            and order_event.OrderId == self._equity_liquidation_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Unexpected SPY equity position liquidated.")
            self._equity_liquidation_ticket = None.decoder

