        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )
        self.option_symbol = self.option.Symbol

        self._closes = []
        self._previous_fast = None
        self._previous_slow = None

        self._current_date = None
        self._bucket_end_minute = None
        self._bucket_closes = {}

        self._pending_signal = False
        self._entry_ticket = None
        self._exit_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._expiration_block_date = None
        self._spy_cleanup_ticket = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        self._handle_unexpected_spy_position()

        if self._held_symbol is not None:
            self._evaluate_exit(slice, today)

        spy_bar = None
        if self.spy_symbol in slice.Bars:
            spy_bar = slice.Bars[self.spy_symbol]

        if spy_bar is not None:
            self._process_minute_bar(spy_bar)

        if self._pending_signal:
            self._pending_signal = False
            self._try_enter(slice, today)

    def _process_minute_bar(self, bar: TradeBar):
        now = self.Time
        current_date = now.date()

        if self._current_date != current_date:
            self._current_date = current_date
            self._bucket_end_minute = None
            self._bucket_closes = {}

        if now.time() < time(9, 30) or now.time() > time(16, 0):
            return

        minute_of_day = now.hour * 60 + now.minute
        session_start = 9 * 60 + 30

        if minute_of_day == session_start:
            bucket_end = session_start + 5
        else:
            bucket_end = (
                ((minute_of_day - session_start + 4) // 5) * 5
                + session_start
            )

        if (
            self._bucket_end_minute is not None
            and bucket_end != self._bucket_end_minute
        ):
            self._finish_bucket()

        if self._bucket_end_minute != bucket_end:
            self._bucket_end_minute = bucket_end
            self._bucket_closes = {}

        self._bucket_closes[minute_of_day] = bar.Close

        if minute_of_day >= bucket_end:
            self._finish_bucket()

    def _finish_bucket(self):
        if self._bucket_end_minute is None:
            return

        end_minute = self._bucket_end_minute
        expected = set(range(end_minute - 4, end_minute + 1))

        if set(self._bucket_closes.keys()) == expected:
            close = self._bucket_closes[end_minute]
            self._on_five_minute_bar(close, end_minute)

        self._bucket_end_minute = None
        self._bucket_closes = {}

    def _on_five_minute_bar(self, close, end_minute):
        if (
            len(self._closes) >= self.SLOW_PERIOD
            and self._previous_fast is not None
            and self._previous_slow is not None
        ):
            current_fast = sum(self._closes[-self.FAST_PERIOD:]) / self.FAST_PERIOD
            current_slow = sum(self._closes[-self.SLOW_PERIOD:]) / self.SLOW_PERIOD

            end_time = time(end_minute // 60, end_minute % 60)

            if (
                time(9, 45) <= end_time <= time(14, 30)
                and self._previous_fast <= self._previous_slow
                and current_fast > current_slow
            ):
                self._pending_signal = True

            self._previous_fast = current_fast
            self._previous_slow = current_slow

        self._closes.append(close)

        if len(self._closes) > self.SLOW_PERIOD:
            self._closes.pop(0)

        if len(self._closes) >= self.SLOW_PERIOD:
            self._previous_fast = (
                sum(self._closes[-self.FAST_PERIOD:]) / self.FAST_PERIOD
            )
            self._previous_slow = (
                sum(self._closes[-self.SLOW_PERIOD:]) / self.SLOW_PERIOD
            )

    def _try_enter(self, slice: Slice, today):
        if self._expiration_block_date == today:
            return

        if self._held_symbol is not None:
            return

        if self._entry_ticket is not None and self._entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        ):
            return

        if self.spy_symbol not in slice.Bars:
            self.Debug("Skipped entry: current SPY price unavailable.")
            return

        spy_price = slice.Bars[self.spy_symbol].Close
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        chains = []
        for chain_symbol in slice.OptionChains:
            chain = slice.OptionChains[chain_symbol]
            if chain is not None:
                chains.append(chain)

        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        eligible_date = today + timedelta(days=7)
        contracts = []

        for chain in chains:
            for contract in chain.Contracts.Values:
                if (
                    contract.Right == OptionRight.Call
                    and contract.Expiry.date() >= eligible_date
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no eligible call expiration.")
            return

        expiration = min(contract.Expiry.date() for contract in contracts)
        strike_floor = spy_price * 1.01

        selected = [
            contract for contract in contracts
            if contract.Expiry.date() == expiration
            and contract.Strike >= strike_floor
        ]

        if not selected:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        contract = selected[0]

        self._entry_ticket = self.MarketOrder(
            contract.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

    def _evaluate_exit(self, slice: Slice, today):
        if self._held_symbol is None:
            return

        contract_security = self.Securities[self._held_symbol]
        expiry_date = contract_security.Symbol.ID.Date.date()

        if today >= expiry_date:
            self._expiration_block_date = today
            self._submit_exit("Expiration liquidation")
            return

        if self._is_immediately_preceding_trading_day(today, expiry_date):
            if self.Time.time() >= time(15, 45):
                self._submit_exit("Pre-expiration time stop")
                return

        if self._entry_price is None:
            return

        quote = None
        if self._held_symbol in slice.QuoteBars:
            quote = slice.QuoteBars[self._held_symbol]

        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self._entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, tag):
        if self._held_symbol is None:
            return

        if self._exit_ticket is not None and self._exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        ):
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity == 0:
            return

        if self._exit_ticket is not None:
            self._exit_ticket.Cancel("Replacing prior exit order")

        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -quantity,
            tag=tag
        )
        self.Debug(f"Exit submitted: {tag}")

    def _is_immediately_preceding_trading_day(self, today, expiry_date):
        if today >= expiry_date:
            return False

        next_day = today + timedelta(days=1)
        exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(next_day):
            next_day += timedelta(days=1)

        return next_day == expiry_date

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy_symbol].Quantity

        if quantity == 0:
            return

        if (
            self._spy_cleanup_ticket is not None
            and self._spy_cleanup_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
            )
        ):
            return

        self.Debug("Unexpected SPY equity position; liquidating immediately.")
        self._spy_cleanup_ticket = self.MarketOrder(
            self.spy_symbol,
            -quantity,
            tag="Unexpected exercise or assignment cleanup"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self._entry_ticket is not None
            and order_event.OrderId == self._entry_ticket.OrderId
        ):
            if (
                order_event.Status == OrderStatus.Filled
                and order_event.FillQuantity > 0
            ):
                self._held_symbol = order_event.Symbol
                self._entry_price = order_event.FillPrice
                self._entry_ticket = None
                self.Debug(
                    f"Entry filled: {self._held_symbol.Value} "
                    f"at {self._entry_price}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected,
            ):
                self._entry_ticket = None

        if (
            self._exit_ticket is not None
            and order_event.OrderId == self._exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(f"Exit filled: {order_event.Symbol.Value}")
            self._exit_ticket = None
            self._held_symbol = None
            self._entry_price = None

        if (
            self._spy_cleanup_ticket is not None
            and order_event.OrderId == self._spy_cleanup_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self._spy_cleanup_ticket = None

