from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyFiveMinuteCallAlgorithm(QCAlgorithm):
    FAST_PERIOD = 5
    SLOW_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.closes = deque(maxlen=self.SLOW_PERIOD)
        self.bucket_key = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.blocked_day = None
        self.equity_liquidation_ticket = None

    def OnData(self, data: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_spy_position(current_date)
        self._process_expiration(current_date)
        self._evaluate_exit(data)

        if self.spy not in data.Bars:
            return

        self._process_spy_minute_bar(data.Bars[self.spy], data)

    def _process_spy_minute_bar(self, bar: TradeBar, data: Slice):
        start = bar.Time
        end = bar.EndTime
        start_time = start.time()

        if start.second != 0:
            return

        session_start = datetime.combine(start.date(), datetime.min.time()).replace(
            hour=9, minute=30
        )
        session_end = datetime.combine(start.date(), datetime.min.time()).replace(
            hour=16, minute=0
        )

        if start < session_start or start >= session_end:
            return

        minutes_from_open = int((start - session_start).total_seconds() // 60)
        bucket_start = session_start + timedelta(
            minutes=(minutes_from_open // 5) * 5
        )
        key = (start.date(), bucket_start.time())

        if self.bucket_key != key:
            self._complete_bucket(data)
            self.bucket_key = key
            self.bucket_bars = {}

        expected_start = bucket_start + timedelta(
            minutes=len(self.bucket_bars)
        )

        if start != expected_start:
            self.bucket_bars[start] = bar
        else:
            self.bucket_bars[start] = bar

        if end.second == 0 and end.minute % 5 == 0:
            self._complete_bucket(data)
            self.bucket_key = None
            self.bucket_bars = {}

    def _complete_bucket(self, data: Slice):
        if self.bucket_key is None or len(self.bucket_bars) != 5:
            return

        bars = sorted(self.bucket_bars.values(), key=lambda item: item.Time)
        for first, second in zip(bars, bars[1:]):
            if second.Time - first.Time != timedelta(minutes=1):
                return

        close = bars[-1].Close
        end_time = bars[-1].EndTime
        self._process_five_minute_close(close, end_time, data)

    def _process_five_minute_close(self, close, end_time, data: Slice):
        if len(self.closes) >= self.SLOW_PERIOD:
            previous_fast = sum(
                list(self.closes)[-self.FAST_PERIOD:]
            ) / float(self.FAST_PERIOD)
            previous_slow = sum(self.closes) / float(self.SLOW_PERIOD)
        else:
            previous_fast = None
            previous_slow = None

        self.closes.append(float(close))

        if len(self.closes) < self.SLOW_PERIOD:
            return

        current_fast = sum(
            list(self.closes)[-self.FAST_PERIOD:]
        ) / float(self.FAST_PERIOD)
        current_slow = sum(self.closes) / float(self.SLOW_PERIOD)

        eligible_time = (
            end_time.time() >= datetime.min.time().replace(hour=9, minute=45)
            and end_time.time() <= datetime.min.time().replace(hour=14, minute=30)
        )

        crossover = (
            previous_fast is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if crossover and eligible_time:
            self._try_enter(data, end_time.date())

    def _try_enter(self, data: Slice, signal_date):
        if self.blocked_day == signal_date:
            return

        if self.held_symbol is not None:
            return

        if self._order_is_open(self.entry_ticket):
            return

        if not data.OptionChains:
            self.Debug("Skipped call selection: no option chain.")
            return

        current_price = self.Securities[self.spy].Price
        if current_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        minimum_expiry = signal_date + timedelta(days=7)
        candidates = []

        for chain in data.OptionChains.Values:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()
                if (
                    expiry_date >= minimum_expiry
                    and contract.Right == OptionRight.Call
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped call selection: no qualifying expiration.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in candidates)
        strike_floor = current_price * 1.01

        strikes = [
            contract for contract in candidates
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= strike_floor
        ]

        if not strikes:
            self.Debug("Skipped call selection: no qualifying strike.")
            return

        selected = min(
            strikes,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} expiring {} strike {:.2f}".format(
                selected.Symbol, nearest_expiry, selected.Strike
            )
        )

    def _evaluate_exit(self, data: Slice):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if holding.Quantity <= 0:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        today = self.Time.date()

        if today >= expiry_date:
            self.blocked_day = today
            self._submit_exit("expiration processing")
            return

        time_stop = (
            self._previous_trading_day(expiry_date) == today
            and self.Time.hour >= 15
            and self.Time.minute >= 45
        )

        midpoint = self._get_current_midpoint(data, self.held_symbol)
        profit_target = (
            midpoint is not None
            and self.entry_price is not None
            and midpoint >= 1.50 * self.entry_price
        )

        if profit_target:
            self._submit_exit("50% profit target")
        elif time_stop:
            self._submit_exit("expiration time stop")

    def _get_current_midpoint(self, data: Slice, symbol):
        for chain in data.OptionChains.Values:
            if symbol in chain.Contracts:
                contract = chain.Contracts[symbol]
                bid = contract.BidPrice
                ask = contract.AskPrice
                if bid > 0 and ask > 0:
                    return (bid + ask) / 2.0
        return None

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self._order_is_open(self.exit_ticket):
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol, -quantity, tag=reason
        )
        self.Debug(
            "Exit submitted: {} ({})".format(self.held_symbol, reason)
        )

    def _process_expiration(self, current_date):
        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        if current_date >= expiry_date:
            self.blocked_day = current_date
            self._submit_exit("expiration processing")

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date()

    def _handle_unexpected_spy_position(self, current_date):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self.blocked_day = current_date

        if not self._order_is_open(self.equity_liquidation_ticket):
            self.equity_liquidation_ticket = self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment"
            )
            self.Debug(
                "Unexpected exercise or assignment: liquidating {} SPY.".format(
                    quantity
                )
            )

    def _order_is_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status in (
                OrderStatus.PartiallyFilled,
                OrderStatus.Filled
            ):
                self.held_symbol = order_event.Symbol
                if order_event.FillPrice > 0:
                    self.entry_price = order_event.FillPrice

                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "Entry filled: {} at {:.4f}".format(
                            order_event.Symbol, order_event.FillPrice
                        )
                    )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {} at {:.4f}".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )
                self.held_symbol = None
                self.entry_price = None
                self.exit_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        if (
            self.equity_liquidation_ticket is not None
            and order_event.OrderId
            == self.equity_liquidation_ticket.OrderId
            and order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        ):
            self.equity_liquidation_ticket = None

