from AlgorithmImports import *
from datetime import timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    FAST_PERIOD = 5
    SLOW_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(timedelta(days=0), timedelta(days=365))
        )

        self.fast = SimpleMovingAverage(self.FAST_PERIOD)
        self.slow = SimpleMovingAverage(self.SLOW_PERIOD)

        self._five_minute_bucket_end = None
        self._five_minute_values = {}
        self._pending_signal = False
        self._signal_price = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.held_expiry = None

        self._last_day = None
        self._no_entry_today = False
        self._assignment_liquidation_ticket = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self._last_day != current_date:
            self._last_day = current_date
            self._no_entry_today = False

        self._handle_unexpected_spy_position()
        self._handle_option_exits(slice)

        bar = slice.Bars.get(self.spy)
        if bar is not None:
            self._process_minute_bar(bar)

        if self._pending_signal:
            self._pending_signal = False
            self._try_enter(slice)

    def _process_minute_bar(self, bar: TradeBar):
        end_time = bar.EndTime
        end_date = end_time.date()
        end_minutes = end_time.hour * 60 + end_time.minute

        if end_minutes <= 9 * 60 + 30 or end_minutes > 16 * 60:
            return

        bucket_minute = ((end_time.minute + 4) // 5) * 5
        bucket_end = end_time.replace(second=0, microsecond=0)

        if bucket_minute >= 60:
            bucket_end = bucket_end.replace(
                hour=end_time.hour + 1,
                minute=0
            )
        else:
            bucket_end = bucket_end.replace(minute=bucket_minute)

        if self._five_minute_bucket_end != bucket_end:
            self._finalize_five_minute_bar()
            self._five_minute_bucket_end = bucket_end
            self._five_minute_values = {}

        self._five_minute_values[end_time] = bar.Close

        if end_time.minute % 5 == 0:
            self._finalize_five_minute_bar()

    def _finalize_five_minute_bar(self):
        if self._five_minute_bucket_end is None:
            return

        bucket_end = self._five_minute_bucket_end
        expected = [
            bucket_end - timedelta(minutes=i)
            for i in range(5, 0, -1)
        ]

        if not all(timestamp in self._five_minute_values for timestamp in expected):
            self._five_minute_values = {}
            return

        close = self._five_minute_values[expected[-1]]

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bucket_end, close)
        self.slow.Update(bucket_end, close)

        if not (self.fast.IsReady and self.slow.IsReady):
            return

        bar_time = bucket_end.time()
        eligible_start = 9 * 60 + 45
        eligible_end = 14 * 60 + 30
        bar_minutes = bar_time.hour * 60 + bar_time.minute

        bullish = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if bullish and eligible_start <= bar_minutes <= eligible_end:
            self._pending_signal = True
            self._signal_price = close

    def _try_enter(self, slice: Slice):
        if self._no_entry_today:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        if self.Portfolio.Invested:
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = []
        for chain in chains:
            for contract in chain:
                expiry_date = contract.Expiry.date()
                if expiry_date >= minimum_expiry:
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no expiration at least 7 days away.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in contracts)
        minimum_strike = 1.01 * self._signal_price

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Entry submitted: {0}".format(selected.Symbol))

    def _handle_option_exits(self, slice: Slice):
        if self.held_symbol is None:
            return

        if self.Portfolio[self.held_symbol].Quantity <= 0:
            return

        current_date = self.Time.date()
        expiry_date = self.held_expiry.date()

        if current_date >= expiry_date:
            self._no_entry_today = True
            self._submit_exit("expiration processing")
            return

        previous_day = expiry_date - timedelta(days=1)
        at_time_stop = (
            current_date == previous_day
            and self.Time.hour == 15
            and self.Time.minute >= 45
        )

        if at_time_stop:
            self._submit_exit("pre-expiration time stop")
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        quote = self._find_current_contract(slice, self.held_symbol)
        if quote is None:
            return

        bid = quote.BidPrice
        ask = quote.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            self.Transactions.CancelOrder(self.entry_ticket.OrderId)

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity > 0:
            self.exit_ticket = self.MarketOrder(
                self.held_symbol,
                -quantity,
                tag=reason
            )
            self.Debug("Exit submitted: {0} ({1})".format(
                self.held_symbol, reason
            ))

    def _find_current_contract(self, slice: Slice, symbol: Symbol):
        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(symbol)
            if contract is not None:
                return contract
        return None

    def _handle_unexpected_spy_position(self):
        holding = self.Portfolio[self.spy]
        if holding.Quantity == 0:
            return

        self._no_entry_today = True

        if (
            self._assignment_liquidation_ticket is None
            or not self._ticket_is_open(self._assignment_liquidation_ticket)
        ):
            self.Debug("Unexpected SPY equity position; liquidating.")
            self._assignment_liquidation_ticket = self.MarketOrder(
                self.spy,
                -holding.Quantity,
                tag="Unexpected exercise or assignment"
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
                and order_event.FillQuantity > 0
            ):
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.held_expiry = self.Securities[
                    self.held_symbol
                ].Symbol.ID.Date

                self.Debug("Entry filled: {0} at {1}".format(
                    self.held_symbol, self.entry_price
                ))

            elif (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug("Exit filled: {0}".format(order_event.Symbol))
                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.held_symbol = None
                    self.entry_price = None
                    self.held_expiry = None
                    self.exit_ticket = None

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Error
            )
        ):
            self.entry_ticket = None

    def _ticket_is_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

