from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyBullishCallStrategy(QCAlgorithm):
    FAST_PERIOD = 5
    SLOW_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.fast_closes = deque(maxlen=self.FAST_PERIOD)
        self.slow_closes = deque(maxlen=self.SLOW_PERIOD)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_key = None
        self.bucket_start = None
        self.bucket_count = 0
        self.bucket_valid = True
        self.bucket_last_time = None
        self.bucket_close = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None
        self.time_stop_date = None
        self.entry_block_date = None
        self.equity_liquidation_ticket = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_equity_position()
        self._process_expiration()
        self._process_option_exit(slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        self._update_five_minute_bar(spy_bar, slice)

    def _update_five_minute_bar(self, bar: TradeBar, slice: Slice):
        bar_time = bar.Time
        current_date = bar_time.date()
        regular_start = datetime(
            current_date.year, current_date.month, current_date.day, 9, 30
        )
        regular_end = datetime(
            current_date.year, current_date.month, current_date.day, 16, 0
        )

        if bar_time < regular_start:
            return

        if bar_time >= regular_end:
            if self.bucket_key is not None:
                self._finalize_bucket(slice)
                self._reset_bucket()
            return

        minutes_from_open = int((bar_time - regular_start).total_seconds() // 60)
        bucket_offset = (minutes_from_open // 5) * 5
        bucket_start = regular_start + timedelta(minutes=bucket_offset)
        bucket_key = (current_date, bucket_start.time())

        if self.bucket_key != bucket_key:
            if self.bucket_key is not None:
                self._finalize_bucket(slice)

            self.bucket_key = bucket_key
            self.bucket_start = bucket_start
            self.bucket_count = 0
            self.bucket_valid = True
            self.bucket_last_time = None
            self.bucket_close = None

        if self.bucket_last_time is not None:
            if bar_time - self.bucket_last_time != timedelta(minutes=1):
                self.bucket_valid = False

        self.bucket_last_time = bar_time
        self.bucket_count += 1
        self.bucket_close = float(bar.Close)

        if self.bucket_count == 5:
            self._finalize_bucket(slice)
            self._reset_bucket()

    def _finalize_bucket(self, slice: Slice):
        if (
            self.bucket_key is None
            or not self.bucket_valid
            or self.bucket_count != 5
            or self.bucket_close is None
        ):
            return

        bar_end = self.bucket_start + timedelta(minutes=5)
        self.slow_closes.append(self.bucket_close)
        self.fast_closes.append(self.bucket_close)

        current_fast = None
        current_slow = None

        if len(self.fast_closes) == self.FAST_PERIOD:
            current_fast = sum(self.fast_closes) / self.FAST_PERIOD

        if len(self.slow_closes) == self.SLOW_PERIOD:
            current_slow = sum(self.slow_closes) / self.SLOW_PERIOD

        bullish_cross = (
            current_fast is not None
            and current_slow is not None
            and self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if bullish_cross:
            eligible_start = datetime(
                bar_end.year, bar_end.month, bar_end.day, 9, 45
            ).time()
            eligible_end = datetime(
                bar_end.year, bar_end.month, bar_end.day, 14, 30
            ).time()

            if eligible_start <= bar_end.time() <= eligible_end:
                self._evaluate_entry(slice)

    def _reset_bucket(self):
        self.bucket_key = None
        self.bucket_start = None
        self.bucket_count = 0
        self.bucket_valid = True
        self.bucket_last_time = None
        self.bucket_close = None

    def _evaluate_entry(self, slice: Slice):
        current_date = self.Time.date()

        if self.entry_block_date == current_date:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        spy_price = self.Securities[self.spy].Price
        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            spy_price = float(spy_bar.Close)

        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        chains = slice.OptionChains
        if chains is None:
            self.Debug("Skipped entry: no option chain.")
            return

        contracts = []
        for chain in chains.Values:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()
                if (
                    contract.Right == OptionRight.Call
                    and expiry_date >= current_date + timedelta(days=7)
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no qualifying expiration.")
            return

        nearest_expiration = min(
            contract.Expiry.date() for contract in contracts
        )

        eligible_contracts = [
            contract
            for contract in contracts
            if contract.Expiry.date() == nearest_expiration
            and contract.Strike >= 1.01 * spy_price
        ]

        if not eligible_contracts:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            eligible_contracts,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="SPY bullish crossover entry"
        )

        self.expiration_date = selected.Expiry.date()
        self.time_stop_date = self._previous_trading_day(self.expiration_date)

    def _process_option_exit(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        if self.Time.time() < datetime(2000, 1, 1, 15, 45).time():
            return

        if self.Time.date() == self.time_stop_date:
            self._submit_exit("SPY call pre-expiration time stop")
            return

        quote = slice.QuoteBars.get(self.held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("SPY call 50 percent profit target")

    def _process_expiration(self):
        if self.expiration_date is None:
            return

        current_date = self.Time.date()

        if current_date >= self.expiration_date:
            self.entry_block_date = current_date

            if (
                self.entry_ticket is not None
                and self._ticket_is_open(self.entry_ticket)
            ):
                self.entry_ticket.Cancel("Expiration processing")

            if (
                self.held_symbol is not None
                and self.Portfolio[self.held_symbol].Invested
            ):
                self._submit_exit("SPY call expiration liquidation")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        quantity = holding.Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: " + reason)

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status in (
                    OrderStatus.Filled,
                    OrderStatus.PartiallyFilled,
                ):
                    self.held_symbol = order_event.Symbol
                    self.entry_price = float(order_event.FillPrice)
                    self.expiration_date = self.Securities[
                        self.held_symbol
                    ].Symbol.ID.Date.date()
                    self.time_stop_date = self._previous_trading_day(
                        self.expiration_date
                    )
                    self.Debug(
                        "Entry filled: "
                        + str(self.held_symbol)
                        + " at "
                        + str(self.entry_price)
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected,
                ):
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status in (
                    OrderStatus.Filled,
                    OrderStatus.PartiallyFilled,
                ):
                    self.Debug("Exit filled: " + str(order_event.Symbol))
                    if not self.Portfolio[order_event.Symbol].Invested:
                        self._clear_option_state()
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected,
                ):
                    self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug("Unexpected option exercise or assignment detected.")
        self._handle_unexpected_equity_position()

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if (
            self.equity_liquidation_ticket is None
            or not self._ticket_is_open(self.equity_liquidation_ticket)
        ):
            self.Debug("Liquidating unexpected SPY equity position.")
            self.equity_liquidation_ticket = self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def _clear_option_state(self):
        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None
        self.time_stop_date = None
        self.exit_ticket = None

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)

        while True:
            candidate_dt = datetime(
                candidate.year,
                candidate.month,
                candidate.day
            )
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate_dt):
                return candidate
            candidate -= timedelta(days=1)

    @staticmethod
    def _ticket_is_open(ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

