            if contract.Expiry.date() == nearest_expiration
            and contract.Strike >= 1.01 * spy_price
        ]

        if not eligible_contracts:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            eligible_contracts,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="SPY bullish crossover entry"
        )

        self.expiration_date = selected.Expiry.date()
        self.time_stop_date = self._previous_trading_day(self.expiration_date)

    def _process_option_exit(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        if self.Time.time() < datetime(2000, 1, 1, 15, 45).time():
            return

        if self.Time.date() == self.time_stop_date:
            self._submit_exit("SPY call pre-expiration time stop")
            return

        quote = slice.QuoteBars.get(self.held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("SPY call 50 percent profit target")

    def _process_expiration(self):
        if self.expiration_date is None:
            return

        current_date = self.Time.date()

        if current_date >= self.expiration_date:
            self.entry_block_date = current_date

            if (
                self.entry_ticket is not None
                and self._ticket_is_open(self.entry_ticket)
            ):
                self.entry_ticket.Cancel("Expiration processing")

            if (
                self.held_symbol is not None
                and self.Portfolio[self.held_symbol].Invested
            ):
                self._submit_exit("SPY call expiration liquidation")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        quantity = holding.Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: " + reason)

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status in (
                    OrderStatus.Filled,
                    OrderStatus.PartiallyFilled,
                ):
                    self.held_symbol = order_event.Symbol
                    self.entry_price = float(order_event.FillPrice)
                    self.expiration_date = self.Securities[
                        self.held_symbol
                    ].Symbol.ID.Date.date()
                    self.time_stop_date = self._previous_trading_day(
                        self.expiration_date
                    )
                    self.Debug(
                        "Entry filled: "
                        + str(self.held_symbol)
                        + " at "
                        + str(self.entry_price)
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected,
                ):
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status in (
                    OrderStatus.Filled,
                    OrderStatus.PartiallyFilled,
                ):
                    self.Debug("Exit filled: " + str(order_event.Symbol))
                    if not self.Portfolio[order_event.Symbol].Invested:
                        self._clear_option_state()
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected,
                ):
                    self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug("Unexpected option exercise or assignment detected.")
        self._handle_unexpected_equity_position()

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if (
            self.equity_liquidation_ticket is None
            or not self._ticket_is_open(self.equity_liquidation_ticket)
        ):
