from AlgorithmImports import *
from collections import defaultdict
from datetime import timedelta


class SpyBullishCallStrategy(QCAlgorithm):
    FAST_PERIOD = 5
    SLOW_PERIOD = 20
    CONTRACTS = 1

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )
        self.option = option.Symbol

        self._minute_buckets = {}
        self._closes = []
        self._fast = None
        self._slow = None
        self._previous_fast = None
        self._previous_slow = None
        self._latest_spy_price = None

        self._entry_ticket = None
        self._entry_order_id = None
        self._held_contract = None
        self._entry_price = None
        self._exit_ticket = None
        self._time_stop_date = None
        self._no_entry_date = None
        self._equity_cleanup_ticket = None

    def OnData(self, slice: Slice):
        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self._latest_spy_price = float(spy_bar.Close)
            self._consume_minute_bar(spy_bar)

        self._handle_unexpected_equity_position()
        self._handle_expiration_processing(slice)
        self._evaluate_open_position_exit(slice)

    def _consume_minute_bar(self, bar: TradeBar):
        end_time = bar.EndTime
        local_time = end_time

        if local_time.date() < self.StartDate.date():
            return

        if local_time.time() < self.TimeRules.At(9, 30).TimeOfDay:
            return

        if local_time.time() > self.TimeRules.At(16, 0).TimeOfDay:
            return

        minutes_from_open = (
            local_time.hour * 60 + local_time.minute
            - (9 * 60 + 30)
        )
        if minutes_from_open <= 0:
            return

        bucket_end_minute = (
            ((minutes_from_open + 4) // 5) * 5
            + 9 * 60 + 30
        )
        bucket_end = local_time.replace(
            hour=bucket_end_minute // 60,
            minute=bucket_end_minute % 60,
            second=0,
            microsecond=0
        )

        bucket = self._minute_buckets.setdefault(
            bucket_end,
            {"open": bar.Open, "high": bar.High, "low": bar.Low,
             "close": bar.Close, "count": 0}
        )
        bucket["high"] = max(bucket["high"], bar.High)
        bucket["low"] = min(bucket["low"], bar.Low)
        bucket["close"] = bar.Close
        bucket["count"] += 1

        if local_time.minute % 5 == 0:
            completed = self._minute_buckets.pop(bucket_end, None)
            if completed is not None:
                self._on_five_minute_bar(
                    bucket_end,
                    float(completed["close"])
                )

    def _on_five_minute_bar(self, end_time, close):
        self._closes.append(close)

        if len(self._closes) >= self.FAST_PERIOD:
            self._fast = sum(self._closes[-self.FAST_PERIOD:]) / self.FAST_PERIOD

        if len(self._closes) >= self.SLOW_PERIOD:
            self._slow = sum(self._closes[-self.SLOW_PERIOD:]) / self.SLOW_PERIOD

        if (
            self._previous_fast is not None
            and self._previous_slow is not None
            and self._fast is not None
            and self._slow is not None
        ):
            bullish_cross = (
                self._previous_fast <= self._previous_slow
                and self._fast > self._slow
            )

            eligible_time = (
                end_time.hour > 9
                or (end_time.hour == 9 and end_time.minute >= 45)
            ) and (
                end_time.hour < 14
                or (end_time.hour == 14 and end_time.minute <= 30)
            )

            if bullish_cross and eligible_time:
                self._try_enter()

        self._previous_fast = self._fast
        self._previous_slow = self._slow

    def _try_enter(self):
        today = self.Time.date()

        if self._no_entry_date == today:
            return

        if self._held_contract is not None:
            return

        if self._entry_ticket is not None and self._is_open(self._entry_ticket):
            return

        if self._latest_spy_price is None:
            self.Debug("Skipped entry: SPY price unavailable.")
            return

        chain = None
        if self.option in self.CurrentSlice.OptionChains:
            chain = self.CurrentSlice.OptionChains[self.option]

        if chain is None:
            self.Debug("Skipped entry: option chain unavailable.")
            return

        minimum_expiry = today + timedelta(days=7)
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 days out.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * self._latest_spy_price

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self._entry_ticket = self.MarketOrder(
            selected.Symbol,
            self.CONTRACTS,
            tag="Bullish five-minute crossover entry"
        )
        self._entry_order_id = self._entry_ticket.OrderId

    def _evaluate_open_position_exit(self, slice: Slice):
        if self._held_contract is None or self._entry_price is None:
            return

        if self._exit_ticket is not None and self._is_open(self._exit_ticket):
            return

        contract = self._find_contract(slice, self._held_contract)
        if contract is not None:
            bid = float(contract.BidPrice)
            ask = float(contract.AskPrice)

            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                if midpoint >= 1.50 * self._entry_price:
                    self._submit_exit("50% profit target")
                    return

        expiry_date = self._held_contract.ID.Date.date()
        preceding_date = expiry_date - timedelta(days=1)

        if (
            self.Time.date() == preceding_date
            and (
                self.Time.hour > 15
                or (self.Time.hour == 15 and self.Time.minute >= 45)
            )
        ):
            if self._time_stop_date != self.Time.date():
                self._time_stop_date = self.Time.date()
                self._submit_exit("expiration-eve time stop")

    def _handle_expiration_processing(self, slice: Slice):
        if self._held_contract is None:
            return

        if self.Time.date() >= self._held_contract.ID.Date.date():
            self._no_entry_date = self.Time.date()
            self._submit_exit("expiration protection")

    def _submit_exit(self, reason):
        if self._held_contract is None:
            return

        quantity = self.Portfolio[self._held_contract].Quantity
        if quantity == 0:
            return

        if self._exit_ticket is not None and self._is_open(self._exit_ticket):
            self._exit_ticket.Cancel("Replacing open exit order")

        self._exit_ticket = self.MarketOrder(
            self._held_contract,
            -quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted: {0}, contract={1}".format(
                reason, self._held_contract
            )
        )

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if (
            self._equity_cleanup_ticket is None
            or not self._is_open(self._equity_cleanup_ticket)
        ):
            self.Debug(
                "Unexpected exercise or assignment handling: liquidating SPY."
            )
            self._equity_cleanup_ticket = self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment cleanup"
            )

        self._no_entry_date = self.Time.date()

    def _find_contract(self, slice: Slice, symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _is_open(self, ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self._entry_order_id is not None
            and order_event.OrderId == self._entry_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self._held_contract = order_event.Symbol
                self._entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled: contract={0}, price={1:.4f}".format(
                        self._held_contract, self._entry_price
                    )
                )
                self._entry_ticket = None
                self._entry_order_id = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self._entry_ticket = None
                self._entry_order_id = None

        if (
            self._exit_ticket is not None
            and order_event.OrderId == self._exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                "Exit filled: contract={0}, price={1:.4f}".format(
                    order_event.Symbol, float(order_event.FillPrice)
                )
            )
            self._held_contract = None
            self._entry_price = None
            self._exit_ticket = None
            self._time_stop_date = None

