                or (self.Time.hour == 15 and self.Time.minute >= 45)
            )
        ):
            if self._time_stop_date != self.Time.date():
                self._time_stop_date = self.Time.date()
                self._submit_exit("expiration-eve time stop")

    def _handle_expiration_processing(self, slice: Slice):
        if self._held_contract is None:
            return

        if self.Time.date() >= self._held_contract.ID.Date.date():
            self._no_entry_date = self.Time.date()
            self._submit_exit("expiration protection")

    def _submit_exit(self, reason):
        if self._held_contract is None:
            return

        quantity = self.Portfolio[self._held_contract].Quantity
        if quantity == 0:
