from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):
    FAST_PERIOD = 5
    SLOW_PERIOD = 20
    MINIMUM_DTE = 7

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast_closes = RollingWindow[float](self.FAST_PERIOD)
        self.slow_closes = RollingWindow[float](self.SLOW_PERIOD)

        self._bucket_end = None
        self._bucket_bars = []
        self._expected_minute = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()

        today = self.Time.date()

        if self.held_symbol is not None:
            expiry = self.held_symbol.ID.Date.date()

            if today >= expiry:
                self.no_entry_date = today
                self.Debug(
                    f"Expiration liquidation: {self.held_symbol.Value}"
                )
                self._submit_exit("expiration")
            else:
                previous_trading_day = self._previous_trading_day(expiry)

                if (
                    today == previous_trading_day
                    and self.Time.hour == 15
                    and self.Time.minute == 45
                ):
                    self.Debug(
                        f"Time-stop liquidation: {self.held_symbol.Value}"
                    )
                    self._submit_exit("time stop")
                else:
                    self._check_profit_target(slice)

        if self.spy not in slice.Bars:
            return

        spy_bar = slice.Bars[self.spy]
        completed_bar = self._consolidate_minute_bar(spy_bar)

        if completed_bar is None:
            return

        crossed = self._update_averages_and_check_crossover(completed_bar)

        if not crossed:
            return

        bar_end = completed_bar.EndTime
        eligible_time = (
            time(9, 45) <= bar_end.time() <= time(14, 30)
        )

        if not eligible_time:
            return

        if self.no_entry_date == today:
            return

        if self.held_symbol is not None or self._entry_order_is_open():
            return

        self._try_enter(slice, completed_bar.Close)

    def _consolidate_minute_bar(self, minute_bar):
        end_time = minute_bar.EndTime
        session_time = end_time.time()

        if (
            end_time.weekday() >= 5
            or session_time < time(9, 31)
            or session_time > time(16, 0)
        ):
            self._reset_bucket()
            return None

        minute = end_time.replace(second=0, microsecond=0)

        if self._bucket_end is None:
            if minute.minute % 5 != 1:
                return None

            self._bucket_end = minute.replace(
                minute=((minute.minute // 5) + 1) * 5
            )
            self._expected_minute = minute
            self._bucket_bars = []

        if minute != self._expected_minute:
            self._reset_bucket()

            if minute.minute % 5 != 1:
                return None

            self._bucket_end = minute.replace(
                minute=((minute.minute // 5) + 1) * 5
            )
            self._expected_minute = minute
            self._bucket_bars = []

        self._bucket_bars.append(minute_bar)
        self._expected_minute = minute + timedelta(minutes=1)

        if minute != self._bucket_end - timedelta(minutes=1):
            return None

        if len(self._bucket_bars) != 5:
            self._reset_bucket()
            return None

        result = TradeBar(
            self._bucket_end - timedelta(minutes=5),
            self.spy,
            self._bucket_bars[0].Open,
            max(bar.High for bar in self._bucket_bars),
            min(bar.Low for bar in self._bucket_bars),
            self._bucket_bars[-1].Close,
            sum(bar.Volume for bar in self._bucket_bars),
            timedelta(minutes=5)
        )

        self._reset_bucket()
        return result

    def _reset_bucket(self):
        self._bucket_end = None
        self._expected_minute = None
        self._bucket_bars = []

    def _update_averages_and_check_crossover(self, bar):
        previous_fast = (
            float(sum(self.fast_closes[i] for i in range(self.FAST_PERIOD)))
            / self.FAST_PERIOD
            if self.fast_closes.IsReady else None
        )
        previous_slow = (
            float(sum(self.slow_closes[i] for i in range(self.SLOW_PERIOD)))
            / self.SLOW_PERIOD
            if self.slow_closes.IsReady else None
        )

        self.fast_closes.Add(float(bar.Close))
        self.slow_closes.Add(float(bar.Close))

        if (
            previous_fast is None
            or previous_slow is None
            or not self.fast_closes.IsReady
            or not self.slow_closes.IsReady
        ):
            return False

        current_fast = float(
            sum(self.fast_closes[i] for i in range(self.FAST_PERIOD))
        ) / self.FAST_PERIOD

        current_slow = float(
            sum(self.slow_closes[i] for i in range(self.SLOW_PERIOD))
        ) / self.SLOW_PERIOD

        return (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

    def _try_enter(self, slice, spy_price):
        if not slice.OptionChains:
            self.Debug("Skipped entry: no option chain")
            return

        algorithm_date = self.Time.date()
        eligible_chains = []

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()

                if (
                    contract.Right == OptionRight.Call
                    and (expiry_date - algorithm_date).days >= self.MINIMUM_DTE
                ):
                    eligible_chains.append(contract)

        if not eligible_chains:
            self.Debug("Skipped entry: no eligible expiration or call")
            return

        nearest_expiry = min(
            contract.Expiry.date() for contract in eligible_chains
        )

        minimum_strike = 1.01 * float(spy_price)
        candidates = [
            contract for contract in eligible_chains
            if (
                contract.Expiry.date() == nearest_expiry
                and contract.Right == OptionRight.Call
                and float(contract.Strike) >= minimum_strike
            )
        ]

        if not candidates:
            self.Debug("Skipped entry: no call at required strike")
            return

        selected = min(
            candidates,
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            f"Entry submitted: {selected.Symbol.Value}, "
            f"strike={selected.Strike}, expiry={selected.Expiry.date()}"
        )

    def _check_profit_target(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        contract = None

        for chain in slice.OptionChains.Values:
            if self.held_symbol in chain.Contracts:
                contract = chain.Contracts[self.held_symbol]
                break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self.Debug(
                f"Profit target reached: {self.held_symbol.Value}, "
                f"midpoint={midpoint:.4f}"
            )
            self._submit_exit("profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity

        if quantity == 0:
            return

        if self._exit_order_is_open():
            self.exit_ticket.Cancel(f"Replaced by {reason}")
            self.exit_ticket = None

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

        self.Debug(
            f"Exit submitted: {self.held_symbol.Value}, reason={reason}"
        )

    def _entry_order_is_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _exit_order_is_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        message = str(order_event.Message or "").lower()

        if (
            "exercise" in message
            or "assign" in message
        ):
            self.Debug(
                f"Unexpected exercise or assignment: "
                f"{order_event.Symbol.Value}"
            )
            self.no_entry_date = self.Time.date()
            self._handle_unexpected_spy_position()

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)

                self.Debug(
                    f"Entry filled: {self.held_symbol.Value}, "
                    f"price={self.entry_price:.4f}"
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol.Value}, "
                    f"price={order_event.FillPrice:.4f}"
                )
                self.held_symbol = None
                self.entry_price = None
                self.exit_ticket = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0:
            self.Debug(
                f"Unexpected SPY equity position detected: quantity={quantity}"
            )
            self.no_entry_date = self.Time.date()
            self.MarketOrder(self.spy, -quantity, tag="unexpected exercise")

    def _previous_trading_day(self, date):
        candidate = date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate
