            bar = slice.Bars[self.spy]
            local_time = bar.Time
            key = (
                local_time.date(),
                local_time.hour,
                (local_time.minute // 5) * 5
            )
            self.minute_counts[key] = self.minute_counts.get(key, 0) + 1
            self.consolidator.Update(bar)

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        interval_start = bar.EndTime - timedelta(minutes=5)
        key = (
            interval_start.date(),
