        if self.held_option is None or self.entry_price is None:
            return
        if self.exit_ticket is not None:
            return
        if self.held_option not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.held_option]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self.SubmitExit("50% profit target")

    def ProcessExpirationAndTimeStop(self):
        if self.held_option is None:
            return

        today = self.Time.date()

        if self.expiration_date is not None and today >= self.expiration_date:
            self.blocked_entry_date = today
            self.SubmitExit("expiration protection")
            return

        if (
            self.time_stop_date is not None
            and today == self.time_stop_date
            and self.Time.hour >= 15
            and self.Time.minute >= 45
        ):
            self.SubmitExit("pre-expiration time stop")

    def SubmitExit(self, reason):
        if self.held_option is None or self.exit_ticket is not None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            self.ClearPositionState()
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug("Call exit submitted: {}".format(reason))

    def HandleUnexpectedUnderlyingPosition(self):
        holding = self.Portfolio[self.spy]
        if holding.Quantity != 0:
            self.blocked_entry_date = self.Time.date()
            self.Debug(
                "Unexpected SPY exercise or assignment; liquidating underlying."
            )
            self.MarketOrder(
                self.spy,
                -holding.Quantity,
                tag="Unexpected exercise or assignment handling"
            )

    def IsEntryOrderOpen(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def PreviousTradingDay(self, date):
        candidate = date - timedelta(days=1)
        hours = self.Securities[self.spy].Exchange.Hours

        while not hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def ClearPositionState(self):
        self.held_option = None
        self.entry_price = None
        self.expiration_date = None
        self.time_stop_date = None
        self.exit_ticket = None

