from AlgorithmImports import *
from datetime import datetime, timedelta
from collections import OrderedDict


class SpyBullishCallAlgorithm(QCAlgorithm):
    FAST_PERIOD = 5
    SLOW_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )
        self.option_canonical = option.Symbol

        self.fast_closes = []
        self.slow_closes = []
        self.previous_fast = None
        self.previous_slow = None

        self._five_minute_bucket = None
        self._five_minute_bars = OrderedDict()

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None

        self.expiration_processed_dates = set()
        self.assignment_dates = set()

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_spy_position(current_date)

        if self.entry_symbol is not None:
            expiration = self.Securities[self.entry_symbol].Symbol.ID.Date.date()
            if current_date >= expiration:
                if self.Portfolio[self.entry_symbol].Invested:
                    self._submit_exit("expiration processing")
                self.expiration_processed_dates.add(current_date)

        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            self._evaluate_exits(slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        self._update_five_minute_bar(spy_bar, slice)

    def _update_five_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        local_end = minute_bar.EndTime.astimezone(self.TimeZone)
        if local_end.weekday() >= 5:
            return

        if local_end.time() < datetime.strptime("09:31", "%H:%M").time():
            return
        if local_end.time() > datetime.strptime("16:00", "%H:%M").time():
            return

        bucket_minute = ((local_end.minute + 4) // 5) * 5
        bucket_end = local_end.replace(
            minute=0,
            second=0,
            microsecond=0
        ) + timedelta(minutes=bucket_minute)

        if self._five_minute_bucket is None:
            self._five_minute_bucket = bucket_end

        if bucket_end != self._five_minute_bucket:
            self._complete_five_minute_bucket(self._five_minute_bucket, slice)
            self._five_minute_bucket = bucket_end
            self._five_minute_bars = OrderedDict()

        if local_end not in self._five_minute_bars:
            self._five_minute_bars[local_end] = minute_bar

        if local_end == bucket_end and len(self._five_minute_bars) == 5:
            self._complete_five_minute_bucket(bucket_end, slice)
            self._five_minute_bucket = None
            self._five_minute_bars = OrderedDict()

    def _complete_five_minute_bucket(self, bucket_end, slice: Slice):
        if len(self._five_minute_bars) != 5:
            self._five_minute_bars = OrderedDict()
            return

        bars = list(self._five_minute_bars.values())
        close = bars[-1].Close

        old_fast = self.previous_fast
        old_slow = self.previous_slow

        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.fast_closes) > self.FAST_PERIOD:
            self.fast_closes.pop(0)
        if len(self.slow_closes) > self.SLOW_PERIOD:
