        self.UpdateFiveMinuteBar(spy_bar, slice)

    def UpdateFiveMinuteBar(self, minute_bar, slice):
        local_time = minute_bar.Time
        if local_time.tzinfo is not None:
            local_time = local_time.replace(tzinfo=None)

        current_date = local_time.date()
        session_start = datetime.combine(current_date, time(9, 30))
        session_end = datetime.combine(current_date, time(16, 0))

        if local_time < session_start or local_time >= session_end:
            return

        elapsed_minutes = int((local_time - session_start).total_seconds() // 60)
        bucket_start = session_start + timedelta(
            minutes=(elapsed_minutes // 5) * 5
        )

        if self.bucket_start != bucket_start:
            self.bucket_start = bucket_start
            self.bucket_minutes = []
            self.bucket_close = None

        if self.bucket_minutes:
            expected_time = self.bucket_minutes[-1] + timedelta(minutes=1)
            if local_time != expected_time:
                self.bucket_minutes = []
                self.bucket_close = None

        if local_time not in self.bucket_minutes:
            self.bucket_minutes.append(local_time)
            self.bucket_close = minute_bar.Close

        if len(self.bucket_minutes) != 5:
            return

        expected_minutes = [
            bucket_start + timedelta(minutes=i) for i in range(5)
        ]

        if self.bucket_minutes != expected_minutes:
            self.bucket_minutes = []
            self.bucket_close = None
            return

        bar_end = bucket_start + timedelta(minutes=5)
        close = self.bucket_close

        self.bucket_minutes = []
        self.bucket_close = None

        self.UpdateAverages(close, bar_end, slice)

    def UpdateAverages(self, close, bar_end, slice):
        self.closes.append(float(close))

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(
            list(self.closes)[-self.fast_period:]
        ) / self.fast_period
        current_slow = sum(self.closes) / self.slow_period

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if not bullish_crossover:
            return

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
