        current_price = self.Securities[self.spy.Symbol].Price

        if current_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        minimum_strike = 1.01 * current_price

        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying strike.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            "Bullish five-minute crossover call entry"
        )

    def GetCurrentOptionChain(self, slice):
        for item in slice.OptionChains:
            if item.Key == self.option.Symbol:
                return item.Value
        return None

    def EvaluateHeldOption(self, slice):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        current_date = self.Time.date()
        current_time = self.Time.time()

        time_stop = (
            current_date == expiry_date - timedelta(days=1)
            and current_time.hour == 15
            and current_time.minute == 45
        )

        if time_stop:
            self.SubmitExit("Expiration-eve time stop")
            return

        chain = self.GetCurrentOptionChain(slice)
        if chain is None:
            return

        contract = None
        for candidate in chain.Contracts.Values:
            if candidate.Symbol == self.held_symbol:
                contract = candidate
                break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self.CancelOpenExitOrder()
