        if self.IsExitOrderOpen():
            return

        quantity = -self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            quantity,
            reason
        )

    def ProcessExpiration(self):
        self.HandleUnexpectedSpyPosition()

        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()

        if expiry_date <= self.Time.date():
            self.no_entry_date = self.Time.date()

            if self.Portfolio[self.held_symbol].Invested:
                self.CancelOpenExitOrder()
                self.SubmitExit("Expiration processing liquidation")

    def HandleUnexpectedSpyPosition(self):
        holding = self.Portfolio[self.spy.Symbol]

        if holding.Quantity != 0:
            self.Debug(
                "Unexpected exercise or assignment created SPY equity; "
                "liquidating entire SPY position."
            )
            self.Liquidate(
                self.spy.Symbol,
                "Unexpected exercise or assignment"
            )

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected option exercise or assignment processed.")
        self.HandleUnexpectedSpyPosition()

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = order_event.Symbol
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        "Entered 1 call: {} at {:.2f}".format(
                            self.held_symbol,
                            self.entry_price
                        )
                    )
                    self.entry_ticket = None
                elif order_event.Status in [
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ]:
                    self.Debug("Call entry order was not filled.")
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "Exited call: {} at {:.2f}".format(
                            order_event.Symbol,
                            order_event.FillPrice
                        )
                    )
                    self.exit_ticket = None
                    self.held_symbol = None
                    self.entry_price = None
                elif order_event.Status in [
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ]:
                    self.exit_ticket = None

    def HasOptionHolding(self):
        if self.held_symbol is not None:
            if self.Portfolio[self.held_symbol].Invested:
                return True

        for security_holding in self.Portfolio.Values:
            symbol = security_holding.Symbol
            if (
                symbol.SecurityType == SecurityType.Option
                and security_holding.Invested
            ):
                return True

        return False

    def IsEntryOrderOpen(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status not in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]

    def IsExitOrderOpen(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status not in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]

    def CancelOpenExitOrder(self):
        if self.IsExitOrderOpen():
            self.exit_ticket.Cancel("Canceling prior exit order")
