            days_to_expiry = (expiry_date - algorithm_date).days

            if days_to_expiry >= 7:
                eligible.append(contract)

        if not eligible:
            self.Debug("Skipped call selection: no eligible expiration.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in eligible)
        current_price = self.Securities[self.spy.Symbol].Price

        if current_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        minimum_strike = 1.01 * current_price

        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying strike.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            "Bullish five-minute crossover call entry"
        )

    def GetCurrentOptionChain(self, slice):
        for item in slice.OptionChains:
            if item.Key == self.option.Symbol:
                return item.Value
        return None

    def EvaluateHeldOption(self, slice):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        current_date = self.Time.date()
        current_time = self.Time.time()

        time_stop = (
            current_date == expiry_date - timedelta(days=1)
            and current_time.hour == 15
            and current_time.minute == 45
        )

        if time_stop:
            self.SubmitExit("Expiration-eve time stop")
            return

        chain = self.GetCurrentOptionChain(slice)
        if chain is None:
            return

        contract = None
        for candidate in chain.Contracts.Values:
            if candidate.Symbol == self.held_symbol:
                contract = candidate
                break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self.CancelOpenExitOrder()
            self.SubmitExit("50 percent profit target")

    def SubmitExit(self, reason):
        if self.held_symbol is None:
            return

        if self.IsExitOrderOpen():
            return

        quantity = -self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            quantity,
            reason
        )

    def ProcessExpiration(self):
        self.HandleUnexpectedSpyPosition()

        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()

        if expiry_date <= self.Time.date():
            self.no_entry_date = self.Time.date()

            if self.Portfolio[self.held_symbol].Invested:
                self.CancelOpenExitOrder()
                self.SubmitExit("Expiration processing liquidation")

    def HandleUnexpectedSpyPosition(self):
        holding = self.Portfolio[self.spy.Symbol]

        if holding.Quantity != 0:
            self.Debug(
                "Unexpected exercise or assignment created SPY equity; "
                "liquidating entire SPY position."
            )
            self.Liquidate(
                self.spy.Symbol,
                "Unexpected exercise or assignment"
            )

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected option exercise or assignment processed.")
        self.HandleUnexpectedSpyPosition()

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = order_event.Symbol
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        "Entered 1 call: {} at {:.2f}".format(
                            self.held_symbol,
                            self.entry_price
                        )
                    )
                    self.entry_ticket = None
                elif order_event.Status in [
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ]:
                    self.Debug("Call entry order was not filled.")
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "Exited call: {} at {:.2f}".format(
                            order_event.Symbol,
                            order_event.FillPrice
                        )
                    )
                    self.exit_ticket = None
                    self.held_symbol = None
                    self.entry_price = None
                elif order_event.Status in [
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ]:
                    self.exit_ticket = None

    def HasOptionHolding(self):
        if self.held_symbol is not None:
            if self.Portfolio[self.held_symbol].Invested:
                return True

        for security_holding in self.Portfolio.Values:
            symbol = security_holding.Symbol
            if (
                symbol.SecurityType == SecurityType.Option
                and security_holding.Invested
            ):
                return True

        return False

    def IsEntryOrderOpen(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status not in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]

    def IsExitOrderOpen(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status not in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]

    def CancelOpenExitOrder(self):
        if self.IsExitOrderOpen():
            self.exit_ticket.Cancel("Canceling prior exit order")

