        if contract is not None:
            bid = float(contract.BidPrice)
            ask = float(contract.AskPrice)
            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                profit_target = midpoint >= float(self.entry_price) * self.PROFIT_MULTIPLIER

        if profit_target:
