            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None:
            if self.exit_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
            ):
                self.exit_ticket.Cancel("Replacing open exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=f"SPY call exit: {reason}"
        )
        self.Debug(f"Exit submitted: {reason}")

    def _find_contract(self, slice: Slice, symbol):
        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            return None

        for contract in chain:
            if contract.Symbol == symbol:
                return contract

        return None

    def _handle_unexpected_underlying_position(self, current_date):
        quantity = self.Portfolio[self.spy.Symbol].Quantity
        if quantity == 0:
            return

        if self.last_assignment_handling_date != current_date:
