from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):
    FAST_PERIOD = 5
    SLOW_PERIOD = 20
    OPTION_MIN_DTE = 7
    OTM_PERCENT = 1.01

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
                                      .Strikes(-200, 200)
                                      .Expiration(0, 365)
        )

        self.fast_values = deque(maxlen=self.FAST_PERIOD)
        self.slow_values = deque(maxlen=self.SLOW_PERIOD)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_end = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.exit_ticket = None

        self.expiration_block_date = None
        self.spy_liquidation_ticket = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        self._liquidate_unexpected_spy_position()

        if self.held_symbol is not None:
            expiry = self.held_symbol.ID.Date.date()

            if today >= expiry:
                self.expiration_block_date = today
                self._submit_exit("expiration")
            else:
                self._evaluate_held_position(slice, today, expiry)

        spy_bar = slice.Bars.get(self.spy_symbol)
        if spy_bar is None:
            return

        consolidated = self._update_five_minute_bar(spy_bar)
        if consolidated is None:
            return

        bar_end, close = consolidated
        self._evaluate_crossover_and_enter(slice, bar_end, close)

    def _update_five_minute_bar(self, minute_bar):
        end = minute_bar.EndTime

        if end.time() < time(9, 31) or end.time() > time(16, 0):
            return None

        minutes_from_open = int((end - datetime.combine(end.date(), time(9, 30))).total_seconds() // 60)
        bucket_number = (minutes_from_open + 4) // 5
        bucket_end = datetime.combine(
            end.date(),
            time(9, 30)
        ) + timedelta(minutes=bucket_number * 5)

        if self.bucket_end != bucket_end:
            self.bucket_end = bucket_end
            self.bucket_bars = {}

        if end not in self.bucket_bars:
            self.bucket_bars[end] = minute_bar

        expected_times = [
            bucket_end - timedelta(minutes=i)
            for i in range(5)
        ]

        if not all(t in self.bucket_bars for t in expected_times):
            return None

        bars = [self.bucket_bars[t] for t in sorted(expected_times)]
        close = bars[-1].Close

        self.bucket_bars = {}
        self.bucket_end = None

        return bucket_end, close

    def _evaluate_crossover_and_enter(self, slice, bar_end, close):
        fast_ready = len(self.fast_values) == self.FAST_PERIOD
        slow_ready = len(self.slow_values) == self.SLOW_PERIOD

        previous_fast = (
            sum(self.fast_values) / len(self.fast_values)
            if fast_ready else None
        )
        previous_slow = (
            sum(self.slow_values) / len(self.slow_values)
            if slow_ready else None
        )

        self.fast_values.append(close)
        self.slow_values.append(close)

        current_fast = (
            sum(self.fast_values) / self.FAST_PERIOD
            if len(self.fast_values) == self.FAST_PERIOD else None
        )
        current_slow = (
            sum(self.slow_values) / self.SLOW_PERIOD
            if len(self.slow_values) == self.SLOW_PERIOD else None
        )

        if (
            previous_fast is None or
            previous_slow is None or
            current_fast is None or
            current_slow is None
        ):
            return

        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)
        bullish_cross = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if eligible_time and bullish_cross:
            self._try_enter(slice, bar_end.date(), close)

    def _try_enter(self, slice, algorithm_date, spy_price):
        if self.expiration_block_date == algorithm_date:
            return

        if self.held_symbol is not None or self._is_open(self.entry_ticket):
            return

        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price")
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain")
            return

