from AlgorithmImports import *
from datetime import datetime, timedelta
from collections import OrderedDict


class SpyFiveMinuteCallStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe.Strikes(-200, 200).Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.fast_values = []
        self.slow_values = []

        self._bucket_key = None
        self._bucket_closes = OrderedDict()

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None

        self.exit_ticket = None
        self.expiration_date = None
        self.blocked_entry_date = None
        self.assignment_liquidation_submitted = False

    def OnData(self, slice: Slice):
        today = self.Time.date()

        self._handle_unexpected_spy_position()
        self._handle_expiration_processing(today)
        self._evaluate_held_option_exit(slice, today)

        if self.entry_ticket is not None:
            if self.entry_ticket.Status in [
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
                OrderStatus.CancelPending
            ]:
                return

        if self.entry_symbol is not None:
            holding = self.Portfolio[self.entry_symbol]
            if holding.Invested or self.entry_ticket is not None:
                return

        if self.blocked_entry_date == today:
            return

        bar = self._get_spy_bar(slice)
        if bar is None:
            return

        completed_bar = self._update_five_minute_bar(bar)
        if completed_bar is None:
            return

        crossover_time = completed_bar.EndTime
        if crossover_time.hour < 9 or crossover_time.hour > 14:
            return
        if crossover_time.hour == 9 and crossover_time.minute < 45:
            return
        if crossover_time.hour == 14 and crossover_time.minute > 30:
            return

        if len(self.fast_values) < self.slow_period:
            return

        fast_current = sum(self.fast_values[-self.fast_period:]) / self.fast_period
        slow_current = sum(self.slow_values[-self.slow_period:]) / self.slow_period

        if len(self.fast_values) <= self.slow_period:
            return

        fast_previous = sum(
            self.fast_values[-self.fast_period - 1:-1]
        ) / self.fast_period
        slow_previous = sum(
            self.slow_values[-self.slow_period - 1:-1]
        ) / self.slow_period

        bullish_crossover = (
            fast_previous <= slow_previous and
            fast_current > slow_current
        )

        if bullish_crossover:
            self._enter_call(slice, completed_bar.Close, today)

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None and
                order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"ENTRY {self.entry_symbol.Value} "
                    f"price={order_event.FillPrice:.2f}"
                )
                return

            if (
                self.exit_ticket is not None and
                order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug(
                    f"EXIT {self.entry_symbol.Value} "
                    f"price={order_event.FillPrice:.2f}"
                )
                self.exit_ticket = None
                self.entry_ticket = None
                self.entry_symbol = None
                self.entry_price = None
                self.expiration_date = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected option exercise or assignment detected")
            self._liquidate_spy_equity()

    def _get_spy_bar(self, slice: Slice):
        try:
            if slice.Bars.ContainsKey(self.spy):
                return slice.Bars[self.spy]
        except Exception:
            pass

        try:
            return slice.Bars[self.spy]
        except Exception:
            return None

    def _update_five_minute_bar(self, bar):
        local_time = self.Time
        if local_time.hour < 9:
            return None
        if local_time.hour == 9 and local_time.minute < 31:
            return None
        if local_time.hour > 16:
            return None
        if local_time.hour == 16 and local_time.minute > 0:
            return None

        bucket_start = local_time - timedelta(minutes=1)
        bucket_start = bucket_start.replace(
            minute=(bucket_start.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self._bucket_key != bucket_start:
            self._bucket_key = bucket_start
            self._bucket_closes = OrderedDict()

        minute_key = local_time.replace(second=0, microsecond=0)
        self._bucket_closes[minute_key] = bar.Close

        if len(self._bucket_closes) < 5:
            return None

        keys = list(self._bucket_closes.keys())
        for i in range(1, len(keys)):
            if keys[i] - keys[i - 1] != timedelta(minutes=1):
                self._bucket_closes = OrderedDict()
                return None

        close = list(self._bucket_closes.values())[-1]
        end_time = bucket_start + timedelta(minutes=5)

        self._bucket_closes = OrderedDict()

        self.fast_values.append(close)
        self.slow_values.append(close)

        if len(self.fast_values) > self.slow_period + 1:
            self.fast_values.pop(0)
            self.slow_values.pop(0)

        return TradeBar(
            self.spy,
            bucket_start,
            end_time,
            close,
            close,
            close,
            close,
            0
        )

    def _enter_call(self, slice: Slice, spy_price: float, today):
        if not slice.OptionChains.ContainsKey(self.option.Symbol):
            self.Debug("SKIP entry: no option chain")
            return

        chain = slice.OptionChains[self.option.Symbol]
        min_expiry = today + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= min_expiry
        })

        if not expirations:
            self.Debug("SKIP entry: no qualifying expiration")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("SKIP entry: no qualifying call strike")
            return

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        selected = candidates[0]

        self.entry_symbol = selected.Symbol
        self.expiration_date = selected_expiry
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(self.entry_symbol, 1)

    def _evaluate_held_option_exit(self, slice: Slice, today):
        if self.entry_symbol is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.entry_symbol]
        if not holding.Invested:
            return

        if self.exit_ticket is not None:
            return

        if (
            self.expiration_date is not None and
            today < self.expiration_date and
            today == self._previous_trading_day(self.expiration_date)
            and self.Time.hour == 15
            and self.Time.minute >= 45
        ):
            self._submit_exit("time stop")
            return

        quote = self._get_current_quote(slice, self.entry_symbol)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit("profit target")

    def _get_current_quote(self, slice: Slice, symbol):
        try:
            if slice.QuoteBars.ContainsKey(symbol):
                quote = slice.QuoteBars[symbol]
                bid = quote.Bid.Close if quote.Bid is not None else 0
                ask = quote.Ask.Close if quote.Ask is not None else 0
                return bid, ask
        except Exception:
            pass

        return None

    def _submit_exit(self, reason):
        if self.entry_symbol is None:
            return

        quantity = self.Portfolio[self.entry_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing open exit order")
            self.exit_ticket = None

        self.exit_ticket = self.MarketOrder(
            self.entry_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"EXIT submitted: {reason}")

    def _handle_expiration_processing(self, today):
        if self.entry_symbol is None or self.expiration_date is None:
            return

        if today >= self.expiration_date:
            self.blocked_entry_date = today
            if self.Portfolio[self.entry_symbol].Invested:
                self._submit_exit("expiration protection")

    def _handle_unexpected_spy_position(self):
        if self.Portfolio[self.spy].Quantity != 0:
            if not self.assignment_liquidation_submitted:
                self.Debug("Unexpected SPY equity position; liquidating")
                self._liquidate_spy_equity()

    def _liquidate_spy_equity(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.MarketOrder(self.spy, -quantity, tag="unexpected assignment")
            self.assignment_liquidation_submitted = True

    def _previous_trading_day(self, date):
        candidate = date - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)
        return candidate

