        self.expiration_date = None
        self.blocked_entry_date = None
        self.assignment_liquidation_submitted = False

    def OnData(self, slice: Slice):
        today = self.Time.date()

        self._handle_unexpected_spy_position()
        self._handle_expiration_processing(today)
        self._evaluate_held_option_exit(slice, today)

        if self.entry_ticket is not None:
            if self.entry_ticket.Status in [
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
                OrderStatus.CancelPending
            ]:
                return

        if self.entry_symbol is not None:
            holding = self.Portfolio[self.entry_symbol]
            if holding.Invested or self.entry_ticket is not None:
                return

        if self.blocked_entry_date == today:
            return

        bar = self._get_spy_bar(slice)
        if bar is None:
            return

        completed_bar = self._update_five_minute_bar(bar)
        if completed_bar is None:
            return

        crossover_time = completed_bar.EndTime
        if crossover_time.hour < 9 or crossover_time.hour > 14:
            return
        if crossover_time.hour == 9 and crossover_time.minute < 45:
            return
        if crossover_time.hour == 14 and crossover_time.minute > 30:
            return

        if len(self.fast_values) < self.slow_period:
            return

        fast_current = sum(self.fast_values[-self.fast_period:]) / self.fast_period
        slow_current = sum(self.slow_values[-self.slow_period:]) / self.slow_period

        if len(self.fast_values) <= self.slow_period:
            return

        fast_previous = sum(
            self.fast_values[-self.fast_period - 1:-1]
        ) / self.fast_period
        slow_previous = sum(
            self.slow_values[-self.slow_period - 1:-1]
        ) / self.slow_period

        bullish_crossover = (
            fast_previous <= slow_previous and
            fast_current > slow_current
        )

        if bullish_crossover:
            self._enter_call(slice, completed_bar.Close, today)

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if (
