        except Exception:
            return None

    def _update_five_minute_bar(self, bar):
        local_time = self.Time
        if local_time.hour < 9:
            return None
        if local_time.hour == 9 and local_time.minute < 31:
            return None
        if local_time.hour > 16:
            return None
        if local_time.hour == 16 and local_time.minute > 0:
            return None

        bucket_start = local_time - timedelta(minutes=1)
        bucket_start = bucket_start.replace(
            minute=(bucket_start.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self._bucket_key != bucket_start:
            self._bucket_key = bucket_start
            self._bucket_closes = OrderedDict()

        minute_key = local_time.replace(second=0, microsecond=0)
        self._bucket_closes[minute_key] = bar.Close

        if len(self._bucket_closes) < 5:
            return None

        keys = list(self._bucket_closes.keys())
        for i in range(1, len(keys)):
            if keys[i] - keys[i - 1] != timedelta(minutes=1):
                self._bucket_closes = OrderedDict()
                return None

        close = list(self._bucket_closes.values())[-1]
        end_time = bucket_start + timedelta(minutes=5)

        self._bucket_closes = OrderedDict()

        self.fast_values.append(close)
        self.slow_values.append(close)

        if len(self.fast_values) > self.slow_period + 1:
            self.fast_values.pop(0)
            self.slow_values.pop(0)

        return TradeBar(
            self.spy,
            bucket_start,
            end_time,
            close,
            close,
            close,
            close,
            0
        )

    def _enter_call(self, slice: Slice, spy_price: float, today):
        if not slice.OptionChains.ContainsKey(self.option.Symbol):
