        min_expiry = today + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= min_expiry
        })

        if not expirations:
            self.Debug("SKIP entry: no qualifying expiration")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("SKIP entry: no qualifying call strike")
            return

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        selected = candidates[0]

        self.entry_symbol = selected.Symbol
        self.expiration_date = selected_expiry
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(self.entry_symbol, 1)

    def _evaluate_held_option_exit(self, slice: Slice, today):
        if self.entry_symbol is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.entry_symbol]
        if not holding.Invested:
            return

        if self.exit_ticket is not None:
            return

        if (
            self.expiration_date is not None and
            today < self.expiration_date and
            today == self._previous_trading_day(self.expiration_date)
            and self.Time.hour == 15
            and self.Time.minute >= 45
        ):
            self._submit_exit("time stop")
            return

        quote = self._get_current_quote(slice, self.entry_symbol)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit("profit target")

    def _get_current_quote(self, slice: Slice, symbol):
        try:
            if slice.QuoteBars.ContainsKey(symbol):
                quote = slice.QuoteBars[symbol]
                bid = quote.Bid.Close if quote.Bid is not None else 0
                ask = quote.Ask.Close if quote.Ask is not None else 0
                return bid, ask
        except Exception:
            pass

        return None

    def _submit_exit(self, reason):
        if self.entry_symbol is None:
            return

        quantity = self.Portfolio[self.entry_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing open exit order")
            self.exit_ticket = None

        self.exit_ticket = self.MarketOrder(
            self.entry_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"EXIT submitted: {reason}")

    def _handle_expiration_processing(self, today):
        if self.entry_symbol is None or self.expiration_date is None:
            return

        if today >= self.expiration_date:
