        bid = None
        ask = None

        if slice.QuoteBars.ContainsKey(self.held_symbol):
            quote = slice.QuoteBars[self.held_symbol]
            bid = quote.Bid.Close
            ask = quote.Ask.Close

        if (bid is None or ask is None or bid <= 0 or ask <= 0):
            for chain in slice.OptionChains.Values:
                if chain.Contracts.ContainsKey(self.held_symbol):
                    contract = chain.Contracts[self.held_symbol]
                    bid = contract.BidPrice
                    ask = contract.AskPrice
                    break

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._SubmitExit("50% profit target")

    def _EvaluateTimeStop(self):
        if self.held_symbol is None or self.held_expiry is None:
            return

        if self.Time.time() != time(15, 45):
            return

        expiry_date = self.held_expiry.date()
        previous_trading_day = self._PreviousTradingDay(expiry_date)

        if self.Time.date() == previous_trading_day:
            self._SubmitExit("expiration-eve time stop")

    def _SubmitExit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ):
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

        self.Debug(
            "Exit submitted for {}: {}".format(
                self.held_symbol,
                reason
            )
        )

    def _PreviousTradingDay(self, expiry_date):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        try:
            return exchange_hours.GetPreviousTradingDay(expiry_date).date()
        except Exception:
            candidate = expiry_date - timedelta(days=1)
            while candidate.weekday() >= 5:
                candidate -= timedelta(days=1)
            return candidate

    def _HandleUnexpectedEquityPosition(self):
        holding = self.Portfolio[self.spy]
        if not holding.Invested:
            return

        self.Debug("Unexpected SPY equity position detected; liquidating immediately")
        self.MarketOrder(
            self.spy,
            -holding.Quantity,
            tag="Unexpected exercise or assignment liquidation"
        )
