            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(self.FAST_PERIOD)
        self.slow = SimpleMovingAverage(self.SLOW_PERIOD)

        self.bucket_date = None
        self.bucket_start = None
        self.bucket_count = 0
        self.bucket_open = None
        self.bucket_high = None
        self.bucket_low = None
        self.bucket_close = None
        self.bucket_volume = 0

        self.entry_ticket = None
        self.entry_symbol = None
        self.held_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.no_entry_date = None
        self.equity_liquidation_ticket = None

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(0, 1),
            self.ProcessExpiration
        )

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self.ProcessTimeStop
        )

    def OnData(self, slice: Slice):
        self.HandleUnexpectedEquityPosition()

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            self.EvaluateProfitTarget(slice)
            return

        local_time = spy_bar.Time
        if local_time.tzinfo is not None:
            local_time = local_time.replace(tzinfo=None)

        if not self.IsRegularSessionMinute(local_time):
            self.EvaluateProfitTarget(slice)
            return

        completed_bar = self.UpdateFiveMinuteBucket(spy_bar, local_time)

        if completed_bar is not None:
            self.ProcessCompletedBar(completed_bar)

            if self.IsEligibleEntryTime(completed_bar["end"]):
                chain = slice.OptionChains.get(self.option_symbol)
                self.TryEnter(chain, completed_bar["close"])

        self.EvaluateProfitTarget(slice)

    def IsRegularSessionMinute(self, time):
        minutes = time.hour * 60 + time.minute
        return 570 <= minutes < 960

    def UpdateFiveMinuteBucket(self, bar, local_time):
        bucket_minute = (local_time.hour * 60 + local_time.minute) // 5 * 5
        bucket_start = datetime(
            local_time.year,
            local_time.month,
            local_time.day
        ) + timedelta(minutes=bucket_minute)

        if self.bucket_start != bucket_start:
            completed = None

            if self.bucket_start is not None and self.bucket_count == 5:
                completed = {
                    "start": self.bucket_start,
                    "end": self.bucket_start + timedelta(minutes=5),
                    "open": self.bucket_open,
                    "high": self.bucket_high,
                    "low": self.bucket_low,
                    "close": self.bucket_close,
                    "volume": self.bucket_volume
                }

            self.bucket_date = local_time.date()
            self.bucket_start = bucket_start
            self.bucket_count = 0
            self.bucket_open = None
            self.bucket_high = None
            self.bucket_low = None
            self.bucket_close = None
            self.bucket_volume = 0

            if completed is not None:
                self.ProcessBucketTransition(bucket_start)

        if self.bucket_count >= 5:
            return None

        if self.bucket_count == 0:
            self.bucket_open = bar.Open
            self.bucket_high = bar.High
            self.bucket_low = bar.Low
        else:
            self.bucket_high = max(self.bucket_high, bar.High)
            self.bucket_low = min(self.bucket_low, bar.Low)

        self.bucket_close = bar.Close
        self.bucket_volume += bar.Volume
        self.bucket_count += 1

        if self.bucket_count == 5:
            return {
                "start": self.bucket_start,
                "end": self.bucket_start + timedelta(minutes=5),
                "open": self.bucket_open,
                "high": self.bucket_high,
                "low": self.bucket_low,
                "close": self.bucket_close,
                "volume": self.bucket_volume
            }

        return None

    def ProcessBucketTransition(self, new_bucket_start):
        if self.bucket_start.date() != new_bucket_start.date():
            self.bucket_count = 0

    def ProcessCompletedBar(self, bar):
        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if previous_ready else None
        previous_slow = self.slow.Current.Value if previous_ready else None

        point = IndicatorDataPoint(self.spy, bar["end"], bar["close"])
        self.fast.Update(point)
        self.slow.Update(point)

        if not (previous_ready and self.fast.IsReady and self.slow.IsReady):
            return

        bullish_cross = (
            previous_fast <= previous_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        if bullish_cross:
            self.last_bullish_cross_time = bar["end"]

