        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def HasOptionHolding(self):
        if self.held_symbol is not None:
            holding = self.Portfolio[self.held_symbol]
            if holding.Invested:
                return True

        for security in self.Securities.Values:
            if security.Symbol.SecurityType == SecurityType.Option:
                if self.Portfolio[security.Symbol].Invested:
                    return True

        return False

    def TryEnter(self, chain, spy_price):
        if self.no_entry_date == self.Time.date():
            return

        if self.HasOpenEntryOrder() or self.HasOptionHolding():
            return

        if chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        if spy_price is None or spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        today = self.Time.date()
        eligible = [
            contract for contract in chain
            if contract.Expiry.date() >= today + timedelta(days=7)
        ]

        if not eligible:
            self.Debug("Skipped call selection: no expiration at least 7 days out.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in eligible)

        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == nearest_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= 1.01 * spy_price
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover call entry"
        )

        self.Debug(
            f"Submitted call entry: {selected.Symbol}, "
            f"expiry={nearest_expiry}, strike={selected.Strike}"
        )

    def EvaluateProfitTarget(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ):
            return

        quote = slice.QuoteBars.get(self.held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2
        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("50% profit target")

    def ProcessTimeStop(self):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        security = self.Securities[self.held_symbol]
        expiry_date = security.Symbol.ID.Date.date()
        today = self.Time.date()

        if self.IsImmediatelyPrecedingTradingDay(today, expiry_date):
            self.SubmitExit("expiration time stop")

    def IsImmediatelyPrecedingTradingDay(self, today, expiry_date):
        if expiry_date <= today:
            return False

        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = today + timedelta(days=1)

        while candidate < expiry_date:
            candidate_dt = datetime(
                candidate.year,
                candidate.month,
                candidate.day
            )

            if exchange_hours.IsDateOpen(candidate_dt):
                return False

            candidate += timedelta(days=1)

        return exchange_hours.IsDateOpen(
            datetime(expiry_date.year, expiry_date.month, expiry_date.day)
        )

    def SubmitExit(self, reason):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        quantity = holding.Quantity

        if quantity == 0:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ):
            self.exit_ticket.Cancel("Replaced by higher-priority exit")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Submitted option exit: {self.held_symbol}, reason={reason}")

    def ProcessExpiration(self):
        today = self.Time.date()

        for security in self.Securities.Values:
            symbol = security.Symbol

            if symbol.SecurityType != SecurityType.Option:
                continue

            holding = self.Portfolio[symbol]
            if not holding.Invested:
                continue

            expiry_date = symbol.ID.Date.date()
            if expiry_date <= today:
                self.no_entry_date = today
                self.held_symbol = symbol
                self.SubmitExit("Expiration protection")

    def HandleUnexpectedEquityPosition(self):
        holding = self.Portfolio[self.spy]
        if holding.Quantity == 0:
            return

        if (
            self.equity_liquidation_ticket is not None and
            self.equity_liquidation_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        ):
            return

        self.Debug(
            f"Unexpected SPY equity position detected: "
            f"{holding.Quantity}. Liquidating immediately."
        )

        self.equity_liquidation_ticket = self.MarketOrder(
            self.spy,
            -holding.Quantity,
            tag="Unexpected exercise or assignment liquidation"
        )

    def OnOrderEvent(self, order_event):
        if order_event.Status not in (
            OrderStatus.Filled,
            OrderStatus.PartiallyFilled
        ):
            return

        if getattr(order_event, "IsAssignment", False):
            self.Debug(
                f"Unexpected option exercise or assignment: "
                f"{order_event.Symbol}"
            )
            self.no_entry_date = self.Time.date()
            self.HandleUnexpectedEquityPosition()

        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId and
            order_event.FillQuantity > 0
        ):
            self.entry_price = order_event.FillPrice
            self.held_symbol = order_event.Symbol

            if order_event.Status == OrderStatus.Filled:
                self.entry_ticket = None

            self.Debug(
                f"Call entry filled: {self.held_symbol}, "
                f"price={self.entry_price}"
            )

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId and
            order_event.FillQuantity < 0
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Call exit filled: {order_event.Symbol}, "
                    f"price={order_event.FillPrice}"
                )
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
                self.entry_symbol = None
                self.no_entry_date = self.Time.date()

