                self.blocked_date = today
                self.SubmitExit("expiration processing")
            else:
                self.EvaluateTimeStop()
                self.EvaluateProfitTarget(slice)

        if self.spy in slice.Bars:
            self.consolidator.Update(slice.Bars[self.spy])

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        bar_end = bar.EndTime.time()

        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not previous_ready or not (self.fast.IsReady and self.slow.IsReady):
            return

        bullish_crossover = (
            previous_fast <= previous_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        if not bullish_crossover:
            return

        if not (time(9, 45) <= bar_end <= time(14, 30)):
            return

        if self.held_symbol is not None or self.EntryOrderIsOpen():
            return

        if self.blocked_date == self.Time.date():
            return

        self.TryEnterCall(bar.Close)

    def TryEnterCall(self, spy_price: float):
        if self.current_slice is None:
            self.Debug("Skipped entry: no current Slice")
            return

        try:
            chains = self.current_slice.OptionChains
            chain_values = chains.Values
        except Exception:
            self.Debug("Skipped entry: no option chain")
            return

        contracts = []
        for chain in chain_values:
            try:
                contracts.extend(chain.Contracts.Values)
            except Exception:
                continue

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        expiries = []
        for contract in contracts:
            try:
                expiry_date = contract.Expiry.date()
                if expiry_date >= minimum_expiry:
                    expiries.append(expiry_date)
            except Exception:
                continue

