            self.Debug("Skipped entry: no qualifying expiration")
            return

        selected_expiry = min(expiries)
        minimum_strike = 1.01 * spy_price

        candidates = []
        for contract in contracts:
            try:
                if (
                    contract.Expiry.date() == selected_expiry and
                    contract.Right == OptionRight.Call and
                    contract.Strike >= minimum_strike
                ):
                    candidates.append(contract)
            except Exception:
                continue

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.pending_expiry = selected_expiry
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish 5-minute crossover entry"
        )
        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"expiry={selected_expiry} strike={selected.Strike}"
        )

    def EvaluateProfitTarget(self, slice: Slice):
        if (
            self.held_symbol is None or
            self.entry_price is None or
            self.exit_submitted
        ):
            return

        contract = None
        try:
            for chain in slice.OptionChains.Values:
                if self.held_symbol in chain.Contracts:
                    contract = chain.Contracts[self.held_symbol]
                    break
        except Exception:
            return

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("50% profit target")

    def EvaluateTimeStop(self):
        if (
            self.held_symbol is None or
            self.contract_expiry is None or
            self.exit_submitted
        ):
            return

        previous_trading_day = self.PreviousTradingDay(self.contract_expiry)

        if (
            self.Time.date() == previous_trading_day and
            self.Time.time() >= time(15, 45)
        ):
            self.SubmitExit("expiration time stop")

    def SubmitExit(self, reason: str):
        if self.held_symbol is None or self.exit_submitted:
            return

        if self.exit_ticket is not None and self.OrderIsOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replaced by liquidation order")

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.exit_submitted = True
        self.Debug(f"Exit submitted: {self.held_symbol} ({reason})")

    def HandleUnexpectedSpyPosition(self, today):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self.blocked_date = today
        self.Debug(
            f"Unexpected exercise or assignment handling: "
            f"liquidating {quantity} SPY shares"
        )
        self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise or assignment liquidation"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if (
                order_event.Status in
                [OrderStatus.PartiallyFilled, OrderStatus.Filled] and
                order_event.FillQuantity > 0
            ):
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.contract_expiry = self.pending_expiry
                self.exit_submitted = False

                self.Debug(
                    f"Entry filled: {self.held_symbol} "
                    f"price={self.entry_price}"
                )

            if order_event.Status in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.entry_ticket = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId and
            order_event.Status == OrderStatus.Filled
        ):
            self.Debug(f"Exit filled: {order_event.Symbol}")
            self.held_symbol = None
            self.entry_price = None
            self.contract_expiry = None
            self.pending_expiry = None
            self.exit_ticket = None
            self.exit_submitted = False

    def EntryOrderIsOpen(self) -> bool:
        return self.entry_ticket is not None and self.OrderIsOpen(self.entry_ticket)

    def OrderIsOpen(self, ticket: OrderTicket) -> bool:
        return ticket.Status not in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]

    def PreviousTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while candidate.weekday() >= 5 or not exchange_hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

