from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyBullishCallAlgorithm(QCAlgorithm):
    FAST_PERIOD = 5
    SLOW_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 370)
        )
        self.option_symbol = option.Symbol

        self._closes = deque(maxlen=self.SLOW_PERIOD)

        self._bucket_date = None
        self._bucket_end_minute = None
        self._bucket_closes = {}

        self._entry_ticket = None
        self._entry_price = None
        self._held_symbol = None
        self._exit_ticket = None
        self._blocked_entry_date = None

    def OnData(self, slice):
        algorithm_date = self.Time.date()

        self._liquidate_unexpected_spy_position()

        spy_bar = None
        if slice.Bars.ContainsKey(self.spy):
            spy_bar = slice.Bars[self.spy]
            self._update_five_minute_bar(spy_bar)

        if self._held_symbol is not None:
            self._process_expiration_and_exits(slice, algorithm_date)

        if spy_bar is not None:
            self._try_entry(slice, spy_bar.Close, algorithm_date)

    def _update_five_minute_bar(self, bar):
        end = bar.EndTime
        local_date = end.date()
        session_start = datetime(local_date.year, local_date.month, local_date.day, 9, 30)

        if end.time() < datetime.min.time().replace(hour=9, minute=31) \
                or end.time() > datetime.min.time().replace(hour=16):
            return

        elapsed_minutes = int((end - session_start).total_seconds() // 60)
        if elapsed_minutes < 1:
            return

        bucket_end_minute = ((elapsed_minutes + 4) // 5) * 5

        if self._bucket_date != local_date:
            if self._bucket_date is not None:
                self._finalize_bucket()
            self._bucket_date = local_date
            self._bucket_end_minute = bucket_end_minute
            self._bucket_closes = {}

        elif bucket_end_minute != self._bucket_end_minute:
            self._finalize_bucket()
            self._bucket_end_minute = bucket_end_minute
            self._bucket_closes = {}

        self._bucket_closes[elapsed_minutes] = bar.Close

    def _finalize_bucket(self):
        if self._bucket_end_minute is None:
            return

        expected = set(
            range(self._bucket_end_minute - 4, self._bucket_end_minute + 1)
        )
        actual = set(self._bucket_closes.keys())

        if expected != actual:
            return

        close = self._bucket_closes[self._bucket_end_minute]
        end_time = datetime(
            self._bucket_date.year,
            self._bucket_date.month,
            self._bucket_date.day,
            9, 30
        ) + timedelta(minutes=self._bucket_end_minute)

        self._on_five_minute_close(close, end_time)

    def _on_five_minute_close(self, close, end_time):
        previous = list(self._closes)

        if len(previous) >= self.SLOW_PERIOD:
            previous_fast = sum(previous[-self.FAST_PERIOD:]) / self.FAST_PERIOD
            previous_slow = sum(previous) / self.SLOW_PERIOD
        else:
            previous_fast = None
            previous_slow = None

        self._closes.append(close)
        current = list(self._closes)

        if len(current) < self.SLOW_PERIOD:
            return

        current_fast = sum(current[-self.FAST_PERIOD:]) / self.FAST_PERIOD
        current_slow = sum(current) / self.SLOW_PERIOD

        bullish_crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if not bullish_crossover:
            return

        if not (time(9, 45) <= end_time.time() <= time(14, 30)):
            return

        self._pending_signal = True
        self._pending_signal_date = end_time.date()

    def _try_entry(self, slice, spy_price, algorithm_date):
        if not getattr(self, "_pending_signal", False):
            return

        self._pending_signal = False

        if self._pending_signal_date != algorithm_date:
            return

        if self._blocked_entry_date == algorithm_date:
            return

        if self._entry_order_open() or self._exit_order_open():
            return

        if self._held_symbol is not None:
            holding = self.Portfolio[self._held_symbol]
            if holding.Invested or holding.Quantity != 0:
                return

        if spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        chains = []
        for chain in slice.OptionChains:
            chains.append(chain)

        if not chains:
            self.Debug("Skipped call selection: no option chain.")
            return

        contracts = []
        for chain in chains:
