        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )
        self.option_symbol = self.option.Symbol

        self.closes = []
        self.minute_buckets = {}
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiry_date = None
        self.expiration_block_date = None
        self.assignment_liquidation_submitted = False

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_spy_position()
        self._handle_expiration_processing(current_date)

        if self.held_symbol is not None:
            self._evaluate_exit(slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        bar_end = self.Time.replace(second=0, microsecond=0)
        if not self._is_regular_session_time(bar_end):
            return

        completed_close, completed_end = self._update_five_minute_bar(
            spy_bar,
            bar_end
        )

        if completed_close is None:
            return

        signal = self._update_averages_and_test_crossover(
            completed_close,
            completed_end
        )

        if signal:
            self._try_enter(slice, completed_close, completed_end)

    def _is_regular_session_time(self, timestamp):
        t = timestamp.time()
        return t >= time(9, 31) and t <= time(16, 0)

    def _update_five_minute_bar(self, minute_bar, bar_end):
        minute = bar_end.minute
        bucket_start_minute = minute - ((minute - 1) % 5)
        bucket_start = bar_end.replace(minute=bucket_start_minute)
        bucket_end = bucket_start + timedelta(minutes=5)

        key = bucket_start

        if key not in self.minute_buckets:
            self.minute_buckets[key] = {
                "bars": {},
                "bucket_end": bucket_end
            }

        bucket = self.minute_buckets[key]
        bucket["bars"][bar_end] = minute_bar

        completed = None

        for old_key in list(self.minute_buckets.keys()):
            if old_key < key:
                old_bucket = self.minute_buckets.pop(old_key)
                expected = [
                    old_key + timedelta(minutes=i)
                    for i in range(1, 6)
                ]
                if all(t in old_bucket["bars"] for t in expected):
                    completed = (
                        old_bucket["bars"][expected[-1]].Close,
                        old_bucket["bucket_end"]
                    )

        return completed if completed is not None else (None, None)

    def _update_averages_and_test_crossover(self, close, bar_end):
        previous_fast = None
        previous_slow = None

        if len(self.closes) >= self.SLOW_PERIOD:
            previous_fast = sum(self.closes[-self.FAST_PERIOD:]) / self.FAST_PERIOD
            previous_slow = sum(self.closes[-self.SLOW_PERIOD:]) / self.SLOW_PERIOD

        self.closes.append(float(close))

        if len(self.closes) < self.SLOW_PERIOD:
            return False

        current_fast = sum(self.closes[-self.FAST_PERIOD:]) / self.FAST_PERIOD
        current_slow = sum(self.closes[-self.SLOW_PERIOD:]) / self.SLOW_PERIOD

        if previous_fast is None or previous_slow is None:
            return False

        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

        return (
            eligible_time
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

    def _try_enter(self, slice, spy_price, bar_end):
        if self.expiration_block_date == self.Time.date():
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = list(chain)
        expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no expiration at least 7 days away.")
            return

        selected_expiry = expiries[0]
        minimum_strike = float(spy_price) * 1.01

        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover"
        )

    def _evaluate_exit(self, slice):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        holding = self.Portfolio[self.held_symbol]
        quantity = holding.Quantity

        if quantity <= 0:
            return

        if self.expiry_date is not None:
            stop_date = self._previous_trading_day(self.expiry_date)
            if (
                self.Time.date() == stop_date
                and self.Time.time() >= time(15, 45)
            ):
                self._submit_exit("Expiration-eve time stop", quantity)
                return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        contract = next(
            (item for item in chain if item.Symbol == self.held_symbol),
            None
        )

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target", quantity)

    def _submit_exit(self, reason, quantity):
        if self.held_symbol is None:
            return

        self.Transactions.CancelOpenOrders(self.held_symbol)

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: " + reason)

    def _handle_expiration_processing(self, current_date):
        if self.held_symbol is None or self.expiry_date is None:
            return

        if current_date >= self.expiry_date:
            self.expiration_block_date = current_date

            if self.entry_ticket is not None and self._ticket_is_open(
                self.entry_ticket
            ):
                self.entry_ticket.Cancel("Expiration processing")

            holding = self.Portfolio[self.held_symbol]
            if holding.Quantity > 0 and (
                self.exit_ticket is None
                or not self._ticket_is_open(self.exit_ticket)
            ):
                self._submit_exit(
                    "Expiration processing liquidation",
                    holding.Quantity
                )

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            self.assignment_liquidation_submitted = False
            return

        if not self.assignment_liquidation_submitted:
            self.Debug("Unexpected exercise or assignment: liquidating SPY.")
            self.MarketOrder(self.spy, -quantity, tag="Unexpected assignment")
            self.assignment_liquidation_submitted = True

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _ticket_is_open(self, ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = self.entry_ticket.Symbol
                self.entry_price = order_event.FillPrice
                self.expiry_date = self.Securities[
                    self.held_symbol
                ].Symbol.ID.Date.date()

                self.Debug(
                    "Entry filled: "
                    + str(self.held_symbol)
                    + " @ "
                    + str(self.entry_price)
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: " + str(self.held_symbol))
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
                self.expiry_date = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None


