            "SPY",
            Resolution.Minute,
            fillDataForward=False,
            extendedMarketHours=False
        ).Symbol

        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.spy_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.spy_consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.spy_consolidator)

        self.fast = SimpleMovingAverage(self.FAST_PERIOD)
        self.slow = SimpleMovingAverage(self.SLOW_PERIOD)

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.option_symbol = self.spy_option.Symbol

        self.current_slice = None
        self.pending_signal = False
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None
        self.expiration_block_date = None
        self.assignment_liquidation_date = None

    def OnFiveMinuteBar(self, sender, bar):
        had_ready_averages = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if had_ready_averages else None
        previous_slow = self.slow.Current.Value if had_ready_averages else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not (had_ready_averages and self.fast.IsReady and self.slow.IsReady):
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        end_time = bar.EndTime
        if not bullish_cross:
            return

        if not (9 * 60 + 45 <= end_time.hour * 60 + end_time.minute <= 14 * 60 + 30):
            return

        self.pending_signal = True

    def OnData(self, slice: Slice):
        self.current_slice = slice
        today = self.Time.date()

        self.HandleUnexpectedEquityPosition(today)
        self.HandleExpirationProcessing(today)
        self.EvaluateExit(slice, today)

        if self.pending_signal:
            self.pending_signal = False
            self.TryEnter(slice, today)

    def TryEnter(self, slice: Slice, algorithm_date):
        if self.expiration_block_date == algorithm_date:
            return

        if self.entry_ticket is not None and self.IsOpen(self.entry_ticket):
            return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            return

        if self.spy not in slice.Bars:
            self.Debug("Skipped selection: current SPY price unavailable.")
            return

        spy_price = slice.Bars[self.spy].Close
        if spy_price is None or spy_price <= 0:
            self.Debug("Skipped selection: invalid current SPY price.")
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped selection: no option chain in current Slice.")
            return

        minimum_expiry = algorithm_date + timedelta(days=7)

        contracts = list(chain.Contracts.Values)
        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped selection: no expiration satisfies the seven-day rule.")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped selection: no qualifying call at selected expiration.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="SPY bullish crossover entry"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol}, "
            f"expiry={selected.Expiry.date()}, strike={selected.Strike}"
        )

    def EvaluateExit(self, slice: Slice, algorithm_date):
        if self.held_symbol is None or not self.Portfolio[self.held_symbol].Invested:
            return

        if self.expiration_date is not None:
            if algorithm_date >= self.expiration_date:
                self.expiration_block_date = algorithm_date
                self.SubmitExit("expiration processing")
                return

            if (
                self.Time.hour == 15
                and self.Time.minute == 45
                and self.IsTradingDayImmediatelyBefore(
                    algorithm_date,
                    self.expiration_date
                )
            ):
                self.SubmitExit("pre-expiration time stop")
                return

        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket):
            return

        if self.held_symbol not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.held_symbol]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.5 * self.entry_price:
            self.SubmitExit("50 percent profit target")

    def SubmitExit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket):
            self.exit_ticket.Cancel(f"Replacing exit: {reason}")

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=f"SPY call exit: {reason}"
        )

        self.Debug(f"Exit submitted: {self.held_symbol}, reason={reason}")

    def HandleExpirationProcessing(self, algorithm_date):
        if self.expiration_date is None:
            return

        if algorithm_date >= self.expiration_date:
            self.expiration_block_date = algorithm_date

            if self.entry_ticket is not None and self.IsOpen(self.entry_ticket):
                self.entry_ticket.Cancel("Expiration processing")

            if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
                self.SubmitExit("expiration processing")

    def HandleUnexpectedEquityPosition(self, algorithm_date):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if self.assignment_liquidation_date == algorithm_date:
            return

        self.assignment_liquidation_date = algorithm_date
        self.expiration_block_date = algorithm_date
        self.Debug(
            f"Unexpected SPY exercise or assignment position detected: "
            f"{quantity} shares. Liquidating immediately."
        )
        self.MarketOrder(self.spy, -quantity, tag="Unexpected exercise/assignment liquidation")

    def OnOrderEvent(self, order_event):
        if order_event.Status == OrderStatus.Filled:
            if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.expiration_date = self.Securities[
                    self.held_symbol
                ].Symbol.ID.Date.date()

                self.Debug(
                    f"Entry filled: {self.held_symbol}, "
                    f"price={self.entry_price}"
                )

            elif self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
                self.Debug(
                    f"Exit filled: {order_event.Symbol}, "
                    f"price={order_event.FillPrice}"
                )
                self.held_symbol = None
                self.entry_price = None
                self.expiration_date = None
                self.exit_ticket = None

        elif order_event.Status in (
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
                self.entry_ticket = None

            if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
                self.exit_ticket = None

    def IsOpen(self, ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def IsTradingDayImmediatelyBefore(self, current_date, expiration_date):
        candidate = current_date + timedelta(days=1)

        while candidate < expiration_date:
            candidate_dt = DateTime(candidate.year, candidate.month, candidate.day)
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate_dt):
                return False
            candidate += timedelta(days=1)

        return candidate == expiration_date and self.Securities[
            self.spy
        ].Exchange.Hours.IsDateOpen(
            DateTime(expiration_date.year, expiration_date.month, expiration_date.day)
        )

