        self.slow_window = RollingWindow[float](self.slow_period)

        self.current_bucket = None
        self.current_bucket_bars = {}

        self.held_option = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None

        self.no_entry_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        # Handle unexpected SPY equity created by exercise or assignment.
        spy_quantity = self.Portfolio[self.spy_symbol].Quantity
        if spy_quantity != 0:
            self.no_entry_date = today
            self.Debug(
                f"Unexpected exercise/assignment: liquidating {spy_quantity} SPY shares."
            )
            self.MarketOrder(
                self.spy_symbol,
                -spy_quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

        # Expiration processing and option exits.
        if self.held_option is not None:
            expiry_date = self.held_option.ID.Date.date()

            if today >= expiry_date:
                self.no_entry_date = today
                self.Debug(
                    f"Expiration processing: liquidating {self.held_option}."
                )
                self._submit_exit("Expiration liquidation")
            else:
                prior_trading_day = self._prior_trading_day(expiry_date)

                if (
                    today == prior_trading_day
                    and self.Time.hour == 15
                    and self.Time.minute >= 45
                ):
                    self.no_entry_date = today
                    self.Debug(
                        f"Time stop: liquidating {self.held_option} before expiration."
                    )
                    self._submit_exit("Pre-expiration time stop")
                else:
                    self._check_profit_target(slice)

        # Build and process a five-minute bar from actual minute bars only.
        crossover = self._update_five_minute_bar(slice)

        if (
            crossover
            and self.fast_window.IsReady
            and self.slow_window.IsReady
            and self.held_option is None
            and self._entry_order_is_closed()
            and self.no_entry_date != today
        ):
            bar_end = self.last_five_minute_end
            if (
                bar_end.hour > 9
                or (bar_end.hour == 9 and bar_end.minute >= 45)
            ) and (
                bar_end.hour < 14
                or (bar_end.hour == 14 and bar_end.minute <= 30)
            ):
                self._try_enter(slice)

    def _update_five_minute_bar(self, slice: Slice) -> bool:
        if not slice.Bars.ContainsKey(self.spy_symbol):
            return False

        minute_bar = slice.Bars[self.spy_symbol]
        end_time = minute_bar.EndTime
        local_end = end_time

        if local_end.hour < 9 or local_end.hour > 16:
            return False

        if local_end.hour == 9 and local_end.minute < 31:
            return False

        # A minute bar ending at 09:31 belongs to the five-minute bar
        # ending at 09:35.
        bucket_minute = ((local_end.minute - 1) // 5 + 1) * 5
        bucket_end = local_end.replace(
            minute=0, second=0, microsecond=0
        ) + timedelta(minutes=bucket_minute)

