            completed = self._complete_bucket()
            self.current_bucket = bucket_end
            self.current_bucket_bars = {}

            # Process the prior bucket before adding the new minute.
            if completed is not None:
                close, completed_end = completed
                return self._process_completed_bar(close, completed_end)

        self.current_bucket_bars[local_end] = minute_bar.Close
        return False

    def _complete_bucket(self):
        if self.current_bucket is None:
            return None

        expected = [
            self.current_bucket - timedelta(minutes=i)
            for i in range(5, 0, -1)
        ]

        if any(timestamp not in self.current_bucket_bars for timestamp in expected):
            self.current_bucket_bars = {}
            return None

        close = self.current_bucket_bars[expected[-1]]
        completed_end = self.current_bucket
        self.current_bucket_bars = {}
        return close, completed_end

    def _process_completed_bar(self, close, completed_end):
        self.last_five_minute_end = completed_end

        previous_fast = None
        previous_slow = None

        if self.fast_window.IsReady:
            previous_fast = sum(self.fast_window) / self.fast_period

        if self.slow_window.IsReady:
            previous_slow = sum(self.slow_window) / self.slow_period

        self.fast_window.Add(close)
        self.slow_window.Add(close)

        if not self.fast_window.IsReady or not self.slow_window.IsReady:
            return False

        current_fast = sum(self.fast_window) / self.fast_period
        current_slow = sum(self.slow_window) / self.slow_period

        return (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

    def _try_enter(self, slice: Slice):
        if not slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Skipped selection: no option chain in current Slice.")
            return

        chain = slice.OptionChains[self.option_symbol]
        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
        ]

        expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped selection: no expiration at least seven days away.")
            return

        selected_expiry = expiries[0]

        if not slice.Bars.ContainsKey(self.spy_symbol):
            self.Debug("Skipped selection: no current SPY price.")
            return

        spy_price = slice.Bars[self.spy_symbol].Close
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in contracts
            if (
                contract.Expiry.date() == selected_expiry
                and contract.Strike >= minimum_strike
            )
        ]

        if not candidates:
            self.Debug("Skipped selection: no qualifying call strike.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.Debug(f"Entry submitted: {selected.Symbol}")

    def _check_profit_target(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        if not slice.OptionChains.ContainsKey(self.option_symbol):
            return

        chain = slice.OptionChains[self.option_symbol]
        held_contract = next(
            (
                contract for contract in chain
                if contract.Symbol == self.held_option
            ),
            None
        )

        if held_contract is None:
            return

        bid = held_contract.BidPrice
        ask = held_contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.Debug(
                f"Profit target reached: {self.held_option}, midpoint {midpoint:.2f}."
            )
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, tag):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None:
            try:
                if not self.exit_ticket.Status.IsClosed():
                    self.exit_ticket.Cancel("Replaced by liquidation exit")
            except Exception:
                pass

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=tag
        )

    def _entry_order_is_closed(self):
        if self.entry_ticket is None:
            return True

        return self.entry_ticket.Status.IsClosed()

    def _prior_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_option = order_event.Symbol
                    self.entry_price = order_event.FillPrice
                    self.entry_ticket = None
                    self.Debug(
                        f"Entry filled: {self.held_option} at "
                        f"{self.entry_price:.4f}."
                    )
                elif order_event.Status.IsClosed():
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(f"Exit filled: {order_event.Symbol}.")
                    self.held_option = None
                    self.entry_price = None
                    self.exit_ticket = None
                elif order_event.Status.IsClosed():
                    self.exit_ticket = None

